Object.assign(quranData,{"52":{"name":"الطور","verses":[{"text":"وَٱلطُّورِ","tafsir":""},{"text":"وَكِتَـٰبٍ مَّسْطُورٍ","tafsir":"قسما بطور سيناء الذي تكلم موسى عليه‌السلام مع ربه من فوقه ، قال جمع من المفسرين أنه جبل بمدين."},{"text":"فِى رَقٍّ مَّنشُورٍ","tafsir":"قسما ب ( كِتابٍ مَسْطُورٍ ) إما المراد أي كتاب ، فالطور مرفوع مكانا ، والكتاب مرفوع معنى ، فالمراد القسم بكل رفيع ، مادي أو معنوي ، أو المراد كتاب خاص ، مثل التوراة والإنجيل والقرآن ، ولا يبعد إرادة الإنجيل باعتبار أنه سبحانه وتعالى حلف بشيء لموسى عليه‌السلام ، وبشيء لعيسى عليه‌السلام وبشيء لمحمد صلى‌الله‌عليه‌وآله‌وسلم « وهو البيت المعمور » . [4] ذلك الكتاب ( فِي رَقٍ ) أي جلد رقيق ( مَنْشُورٍ ) نشر لقراءته ، ولعل القصد من الصفات إفادة وضوحه ، فالكتابة مسطورة ، لا مندمجة بعضها في بعض ، وهي في ورق قد نشر ، يقرأه كل إنسان ، فالكتابة جمعت بين الارتفاع معنى الظهور ، كما أن الطور جمع بين الارتفاع مادة الظهور."},{"text":"وَٱلْبَيْتِ ٱلْمَعْمُورِ","tafsir":""},{"text":"وَٱلسَّقْفِ ٱلْمَرْفُوعِ","tafsir":"قسما ب ( الْبَيْتِ الْمَعْمُورِ ) الكعبة المعظمة ، أو الضراح في السماء الرابعة أو السابعة."},{"text":"وَٱلْبَحْرِ ٱلْمَسْجُورِ","tafsir":"قسما ب ( السَّقْفِ الْمَرْفُوعِ ) السماء ، لأنه سقف يمنع وصول أحجار النيازك إلى الأرض ، والمراد به بعض طبقات السماء."},{"text":"إِنَّ عَذَابَ رَبِّكَ لَوَٰقِعٌ","tafsir":"قسما ب ( الْبَحْرِ الْمَسْجُورِ ) الذي له أمواج كشعل النيران ، أو إِنَّ عَذابَ رَبِّكَ لَواقِعٌ (7) ما لَهُ مِنْ دافِعٍ (8) يَوْمَ تَمُورُ السَّماءُ مَوْراً (9) وَتَسِيرُ الْجِبالُ سَيْراً (10) فَوَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّبِينَ (11) الَّذِينَ هُمْ فِي خَوْضٍ يَلْعَبُونَ (12) يَوْمَ يُدَعُّونَ إِلى نارِ جَهَنَّمَ دَعًّا (13) المراد به حين ينقلب نيرانا ، كما في أهوال القيامة."},{"text":"مَّا لَهُۥ مِن دَافِعٍ","tafsir":"على الكفار ( لَواقِعٌ ) قطعا."},{"text":"يَوْمَ تَمُورُ ٱلسَّمَآءُ مَوْرًا","tafsir":"ليس للعذاب ( مِنْ دافِعٍ ) يدفعه عن الكفار ، فكأن الإنسان يسرح بخياله إلى السماء ، والجبل ، والبحر ، وبيت مرتفع في وسطها ، وكتاب نشر في أحوال الكون ، « كتاب تكويني إلى جانبه كتاب تشريعي » ألا يدل كل ذلك على عظيم القدرة ؟ إذا فلا بد وأن يذوقوا العذاب. [10] وإنما يقع العذاب ( يَوْمَ تَمُورُ ) تضطرب ( السَّماءُ مَوْراً ) لأن النظام الكوني ينهدم فتضطرب الكواكب."},{"text":"وَتَسِيرُ ٱلْجِبَالُ سَيْرًا","tafsir":""},{"text":"فَوَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ","tafsir":"كالسحاب السائر ( سَيْراً ) مفعول مطلق للتأكيد."},{"text":"ٱلَّذِينَ هُمْ فِى خَوْضٍ يَلْعَبُونَ","tafsir":"وسوء ( يَوْمَئِذٍ ) في هذا اليوم ( لِلْمُكَذِّبِينَ ) بالله وبرسوله وبالمعاد."},{"text":"يَوْمَ يُدَعُّونَ إِلَىٰ نَارِ جَهَنَّمَ دَعًّا","tafsir":"يخوضون في الكفر والعصيان ( يَلْعَبُونَ ) فإن عمل من لا يفكر في العاقبة لعب إذ لا هدف حقيقي له ، وإن تصور أن له هدفا. [14] وذلك في ( يَوْمَ يُدَعُّونَ ) الدعّ الدفع العنيف ( إِلى نارِ جَهَنَّمَ دَعًّا ) هذِهِ النَّارُ الَّتِي كُنْتُمْ بِها تُكَذِّبُونَ (14) أَ فَسِحْرٌ هذا أَمْ أَنْتُمْ لا تُبْصِرُونَ (15) اصْلَوْها فَاصْبِرُوا أَوْ لا تَصْبِرُوا سَواءٌ عَلَيْكُمْ إِنَّما تُجْزَوْنَ ما كُنْتُمْ تَعْمَلُونَ (16) إِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ وَنَعِيمٍ (17) مفعول مطلق لتأكيد العنف في سوقهم إلى جهنم. [15] ويقال لهم ( هذِهِ النَّارُ الَّتِي كُنْتُمْ بِها تُكَذِّبُونَ ) وكنتم تقولون أن ما جاء به محمد صلى‌الله‌عليه‌وآله‌وسلم سحر لا أصل له."},{"text":"هَـٰذِهِ ٱلنَّارُ ٱلَّتِى كُنتُم بِهَا تُكَذِّبُونَ","tafsir":""},{"text":"أَفَسِحْرٌ هَـٰذَآ أَمْ أَنتُمْ لَا تُبْصِرُونَ","tafsir":""},{"text":"ٱصْلَوْهَا فَٱصْبِرُوٓا۟ أَوْ لَا تَصْبِرُوا۟ سَوَآءٌ عَلَيْكُمْ ۖ إِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ","tafsir":"الذي ترونه في النار ؟ يقال لهم ذلك تبكيتا ( أَمْ أَنْتُمْ لا تُبْصِرُونَ ) أن هذه نار ؟ كما كنتم تقولون في الدنيا ، إنا لا نراك ( وَمِنْ بَيْنِنا وَبَيْنِكَ حِجابٌ ) (1) ."},{"text":"إِنَّ ٱلْمُتَّقِينَ فِى جَنَّـٰتٍ وَنَعِيمٍ","tafsir":"ذوقوا النار ( فَاصْبِرُوا أَوْ لا تَصْبِرُوا ) بأن تجزعوا ( سَواءٌ عَلَيْكُمْ ) أي الصبر وعدمه ، فأيهما لا يخفف من عذابكم ( إِنَّما تُجْزَوْنَ ما كُنْتُمْ تَعْمَلُونَ ) ظاهره نفس عملكم إذ قد ذكرنا في بعض السور أن نفس العمل صار جزاء كما أن نفس البيضة والنواة تصير فرخا وشجرة ، ومن الواضح أن في مثل هذا المقام لا فرق بين الصبر والجزع ولعل هذا الكلام للكفار ، جزاء لما كانوا يقولونه للأنبياء إنهم لا يقبلون كلامهم في كل الأحوال ، فجزاؤهم النار في كل الأحوال. [18] وفي مقابل هؤلاء المكذبين المصدقون ف ( إِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ وَنَعِيمٍ ) النعمة الباطنية « الجنة الظاهرية » كما أن الكفار في ألم النار ( 1) فصلت : 6. فاكِهِينَ بِما آتاهُمْ رَبُّهُمْ وَوَقاهُمْ رَبُّهُمْ عَذابَ الْجَحِيمِ (18) كُلُوا وَاشْرَبُوا هَنِيئاً بِما كُنْتُمْ تَعْمَلُونَ (19) مُتَّكِئِينَ عَلى سُرُرٍ مَصْفُوفَةٍ وَزَوَّجْناهُمْ بِحُورٍ عِينٍ (20) وألم التوبيخ والاستهزاء ، كما في « أ فسحر ؟ فاصبروا .. . » ."},{"text":"فَـٰكِهِينَ بِمَآ ءَاتَىٰهُمْ رَبُّهُمْ وَوَقَىٰهُمْ رَبُّهُمْ عَذَابَ ٱلْجَحِيمِ","tafsir":""},{"text":"كُلُوا۟ وَٱشْرَبُوا۟ هَنِيٓـًٔۢا بِمَا كُنتُمْ تَعْمَلُونَ","tafsir":"متلذذين ( بِما آتاهُمْ ) أعطاهم ( رَبُّهُمْ ) من النعم ( وَوَقاهُمْ رَبُّهُمْ عَذابَ الْجَحِيمِ ) أي حفظهم من ذلك العذاب ، إشارة إلى أنهم وإن استحقوا العذاب لبعض معاصيهم إلا أن الله يغفر لهم ويحفظهم من ذلك العذاب لطفا وتفضلا. [20] ويقال لهم ( كُلُوا وَاشْرَبُوا هَنِيئاً ) الهنيء الذي لا تنغيص فيه لا من جهة الفم ولا من جهة الحلق عند الازدراء ولا من جهة العاقبة فلا أثر سيئ له بسبب ما ( كُنْتُمْ تَعْمَلُونَ ) من العقيدة الصحيحة ، والأعمال الصحيحة ، فإن العقيدة نوع عمل للقلب حيث بنى على شيء معين. [21] في حال كونهم ( مُتَّكِئِينَ عَلى سُرُرٍ ) جمع سرير ( مَصْفُوفَةٍ ) قد اصطفت ففيه جمال للمنظر بالإضافة إلى كونه راحة للجسم ( وَزَوَّجْناهُمْ بِحُورٍ عِينٍ ) جمع حوراء واسعة العين وبيضاء الجسم فنظافة في الأبدان والأخلاق ، وعيناه واسعة العين بما يزيدها جمالا ، وقد وردت في الروايات تزويج النساء أيضا برجال الدنيا ، ولعل عدم ذكر النساء وزواجهن من باب البلاغة ، لأنه من غير المستحسن لدى العرف أن يقال للمرأة نزوجك ، بخلاف أن يقال للرجل. [22] ثم إن أولاد المؤمنين الذين لا يستحقون بأعمالهم مراتب آبائهم في وَالَّذِينَ آمَنُوا وَاتَّبَعَتْهُمْ ذُرِّيَّتُهُمْ بِإِيمانٍ أَلْحَقْنا بِهِمْ ذُرِّيَّتَهُمْ وَما أَلَتْناهُمْ مِنْ عَمَلِهِمْ مِنْ شَيْءٍ كُلُّ امْرِئٍ بِما كَسَبَ رَهِينٌ (21) وَأَمْدَدْناهُمْ بِفاكِهَةٍ وَلَحْمٍ مِمَّا يَشْتَهُونَ (22) الجنة ، يلحقون بآبائهم لتقدير إيمان الآباء ( وَالَّذِينَ آمَنُوا وَاتَّبَعَتْهُمْ ذُرِّيَّتُهُمْ بِإِيمانٍ ) بأن لم يكونوا كفرة ( أَلْحَقْنا بِهِمْ ذُرِّيَّتَهُمْ ) حتى ينعم الآباء بمؤانسة الأولاد ، فمرة يشتغلون بالحور العين ، وتارة بالذرية ، وفي ذلك قرة أعينهم ( وَما أَلَتْناهُمْ ) أي ما نقصنا الآباء ( مِنْ عَمَلِهِمْ مِنْ شَيْءٍ ) فلم نعطي للأبناء من حق الآباء بل أعطينا الأبناء زيادة على حق الآباء ( كُلُّ امْرِئٍ بِما كَسَبَ رَهِينٌ ) كأن نفس الإنسان مرهونة بالعمل الصالح فإذا أعطى الله العامل استرجع نفسه فصار حرا ، وإلا بقي أسيرا في جهنم ، لأنه لم يقدم ما يفك به نفسه ، كما أن صاحب الدار الذي رهنها لأنه لم يقدم مال المرتهن لم يتمكن من استرداد داره ، ولعل قوله سبحانه ( كُلُّ امْرِئٍ .. . ) لدفع توهم أنه إذا أعطى الذرية ما لا يستحقون فقد حصلوا الثواب بغير عمل ؟ والجواب كلا ، إن الذرية كانوا مؤمنين فاستحقوا الجنة بذلك ، ولكن الله تفضل عليهم بالمزيد جزاء للآباء فدرجتهم بين جزاء لهم وجزاء لآبائهم ، أو يقال إن كلا من الآباء والذرية استحق نفس الدرجة الرفيعة واستحق الجمع بينها ، فالآية إخبار عن الواقع ، ولا إعطاء لما لا يستحق ولو إعطاء تفضلا."},{"text":"مُتَّكِـِٔينَ عَلَىٰ سُرُرٍ مَّصْفُوفَةٍ ۖ وَزَوَّجْنَـٰهُم بِحُورٍ عِينٍ","tafsir":""},{"text":"وَٱلَّذِينَ ءَامَنُوا۟ وَٱتَّبَعَتْهُمْ ذُرِّيَّتُهُم بِإِيمَـٰنٍ أَلْحَقْنَا بِهِمْ ذُرِّيَّتَهُمْ وَمَآ أَلَتْنَـٰهُم مِّنْ عَمَلِهِم مِّن شَىْءٍ ۚ كُلُّ ٱمْرِئٍۭ بِمَا كَسَبَ رَهِينٌ","tafsir":""},{"text":"وَأَمْدَدْنَـٰهُم بِفَـٰكِهَةٍ وَلَحْمٍ مِّمَّا يَشْتَهُونَ","tafsir":""},{"text":"يَتَنَـٰزَعُونَ فِيهَا كَأْسًا لَّا لَغْوٌ فِيهَا وَلَا تَأْثِيمٌ","tafsir":"استمررنا في إمدادهم ، فليس كالضيافات ، في الدنيا التي يؤتى إلى الضيف بالمأكول والمشروب أول ما يجيء فقط ، فإذا جلس ساعة مثلا ، لا يؤتى إليه مرة أخرى بهما ( بِفاكِهَةٍ وَلَحْمٍ مِمَّا يَشْتَهُونَ ) يَتَنازَعُونَ فِيها كَأْساً لا لَغْوٌ فِيها وَلا تَأْثِيمٌ (23) وَيَطُوفُ عَلَيْهِمْ غِلْمانٌ لَهُمْ كَأَنَّهُمْ لُؤْلُؤٌ مَكْنُونٌ (24) وَأَقْبَلَ بَعْضُهُمْ عَلى بَعْضٍ يَتَساءَلُونَ (25) قالُوا إِنَّا كُنَّا قَبْلُ فِي أَهْلِنا مُشْفِقِينَ (26) فَمَنَّ اللهُ عَلَيْنا وَوَقانا عَذابَ السَّمُومِ (27) واللحم شامل للطير والسمك وسائر اللحوم."},{"text":"۞ وَيَطُوفُ عَلَيْهِمْ غِلْمَانٌ لَّهُمْ كَأَنَّهُمْ لُؤْلُؤٌ مَّكْنُونٌ","tafsir":"على سبيل المزاح والمفاكهة ( فِيها ) في الجنة ( كَأْساً ) فيها خمر ( لا لَغْوٌ فِيها ) لا يتكلمون إذا شربوها باللغو ( وَلا تَأْثِيمٌ ) من ما يفعله شاربوا الخمر في الدنيا من السب والضرب والجرح وأحيانا التعدي على الأعراض وغيرها ، فإنه لا فساد في الآخرة."},{"text":"وَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍ يَتَسَآءَلُونَ","tafsir":"يمر بهم مرورا متواصلا ، لإعطائهم الكأس والفاكهة وقضاء حوائجهم ( غِلْمانٌ ) جمع غلام ( لَهُمْ كَأَنَّهُمْ ) في بياضهم وجمالهم ( لُؤْلُؤٌ مَكْنُونٌ ) محفوظ في مكان نظيف بحيث لم يكن ظاهرا حتى يغير بريقه الهواء والوسخ."},{"text":"قَالُوٓا۟ إِنَّا كُنَّا قَبْلُ فِىٓ أَهْلِنَا مُشْفِقِينَ","tafsir":"من أهل الجنة ( عَلى بَعْضٍ يَتَساءَلُونَ ) هذا يسأل ذاك وذاك يسأل هذا عن أحوالهم في الدنيا وما استحقوا به هذه الدرجات ؟"},{"text":"فَمَنَّ ٱللَّهُ عَلَيْنَا وَوَقَىٰنَا عَذَابَ ٱلسَّمُومِ","tafsir":"المسؤولون ( إِنَّا كُنَّا قَبْلُ ) في دار الدنيا حيث كنا ( فِي أَهْلِنا مُشْفِقِينَ ) خائفين من العذاب ، إذ من لا خوف له لا يعمل صالحا ـ إلا في الأندر من النادر ـ ."},{"text":"إِنَّا كُنَّا مِن قَبْلُ نَدْعُوهُ ۖ إِنَّهُۥ هُوَ ٱلْبَرُّ ٱلرَّحِيمُ","tafsir":"بغفران ذنوبنا ( وَوَقانا ) حفظنا ( عَذابَ السَّمُومِ ) إِنَّا كُنَّا مِنْ قَبْلُ نَدْعُوهُ إِنَّهُ هُوَ الْبَرُّ الرَّحِيمُ (28) فَذَكِّرْ فَما أَنْتَ بِنِعْمَةِ رَبِّكَ بِكاهِنٍ وَلا مَجْنُونٍ (29) أَمْ يَقُولُونَ شاعِرٌ نَتَرَبَّصُ بِهِ رَيْبَ الْمَنُونِ (30) قُلْ تَرَبَّصُوا فَإِنِّي مَعَكُمْ مِنَ النار النافذة في المسام وثقب الجسد."},{"text":"فَذَكِّرْ فَمَآ أَنتَ بِنِعْمَتِ رَبِّكَ بِكَاهِنٍ وَلَا مَجْنُونٍ","tafsir":"في دار الدنيا ( نَدْعُوهُ ) ندعو الله سبحانه ، ولا ندعو غيره ( إِنَّهُ ) سبحانه ( هُوَ الْبَرُّ ) المحسن ( الرَّحِيمُ ) ، ولذا أحسن إلينا ورحمنا ، رحمنا فلم يعذبنا بذنوبنا ، وأحسن إلينا بإعطائنا أزيد من استحقاقنا."},{"text":"أَمْ يَقُولُونَ شَاعِرٌ نَّتَرَبَّصُ بِهِۦ رَيْبَ ٱلْمَنُونِ","tafsir":"يا رسول الله الناس بالعقائد الصحيحة ولا يمنعك من الاستمرار في التذكير سبهم لك واتهامهم إياك بأنك كاهن أو مجنون ( فَما أَنْتَ بِنِعْمَةِ رَبِّكَ ) بسبب إنعامه الذي أعطاك تعالى ( بِكاهِنٍ ) متصل بالجن يخبره بعض الأخبار الغائبة عن الحواس ( وَلا مَجْنُونٍ ) دخل فيه الجان فأخذ يتكلم ببعض المغيبات ـ كما كانوا يتهمون الرسول صلى‌الله‌عليه‌وآله‌وسلم بهذين الأمرين ـ ."},{"text":"قُلْ تَرَبَّصُوا۟ فَإِنِّى مَعَكُم مِّنَ ٱلْمُتَرَبِّصِينَ","tafsir":"بل يقولون أن محمدا صلى‌الله‌عليه‌وآله‌وسلم ( شاعِرٌ ) إذا رأوا عدم قبول الناس افترائهم الأول « إنه كاهن أو مجنون » . ( نَتَرَبَّصُ بِهِ ) أي نصبر وننتظر ( رَيْبَ الْمَنُونِ ) أي ما يقلق النفوس من حوادث الدهر ، فإذا احتفت به المشاكل انقلع عن دعواه النبوة ، أو المراد بالمنون الموت."},{"text":"أَمْ تَأْمُرُهُمْ أَحْلَـٰمُهُم بِهَـٰذَآ ۚ أَمْ هُمْ قَوْمٌ طَاغُونَ","tafsir":"لهم يا رسول الله ( تَرَبَّصُوا ) انتظروا ( فَإِنِّي مَعَكُمْ مِنَ الْمُتَرَبِّصِينَ (31) أَمْ تَأْمُرُهُمْ أَحْلامُهُمْ بِهذا أَمْ هُمْ قَوْمٌ طاغُونَ (32) أَمْ يَقُولُونَ تَقَوَّلَهُ بَلْ لا يُؤْمِنُونَ (33) فَلْيَأْتُوا بِحَدِيثٍ مِثْلِهِ إِنْ كانُوا صادِقِينَ (34) أَمْ خُلِقُوا مِنْ غَيْرِ شَيْءٍ أَمْ هُمُ الْخالِقُونَ (35) الْمُتَرَبِّصِينَ ) فكما أنكم تنتظرون هلاكي وعدم نجاحي ، فإني أنتظر نجاحي وتقدم دعوتي ، أو أنتظر موتكم ، وسوف نرى العاقبة لمن ؟."},{"text":"أَمْ يَقُولُونَ تَقَوَّلَهُۥ ۚ بَل لَّا يُؤْمِنُونَ","tafsir":"عقولهم ( بِهذا ) التناقض في أقوالهم فمرة يقولون شاعر ، وأخرى كاهن وثالثة مجنون ، فهل أمثال هذه الكلمات تصدر من العقلاء ؟ ( أَمْ هُمْ قَوْمٌ طاغُونَ ) يعرفون الحق ، وإنما يقولون الباطل لطغيانهم على الحق ، وعنادهم في الأمر."},{"text":"فَلْيَأْتُوا۟ بِحَدِيثٍ مِّثْلِهِۦٓ إِن كَانُوا۟ صَـٰدِقِينَ","tafsir":"أي اختلق الرسول صلى‌الله‌عليه‌وآله‌وسلم القرآن من تلقاء نفسه بدون أن ينزل عليه وحي ( بَلْ ) هم يعلمون وإنما لأنهم ( لا يُؤْمِنُونَ ) يرمون القرآن بهذه الأمور حتى يجعلوا لأنفسهم عذرا في عدم إيمانهم. [35] وإذا كان تقوّل من الرسول ( فَلْيَأْتُوا بِحَدِيثٍ ) شيء جديد ( مِثْلِهِ ) مثل القرآن ( إِنْ كانُوا صادِقِينَ ) في قولهم « تقوله » إذ لو كان القرآن كلام البشر لتمكن بلغائهم أن يأتوا بمثله ، فعدم تمكنهم بأجمعهم من الإتيان بمثل القرآن دليل عدم كون القرآن من كلام البشر."},{"text":"أَمْ خُلِقُوا۟ مِنْ غَيْرِ شَىْءٍ أَمْ هُمُ ٱلْخَـٰلِقُونَ","tafsir":""},{"text":"أَمْ خَلَقُوا۟ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ ۚ بَل لَّا يُوقِنُونَ","tafsir":"خالق لهم ولذا لا يذعنون بالخالق ولا يسمعون كلامه ( أَمْ هُمُ الْخالِقُونَ ) خلقوا أنفسهم ؟ وحيث لا هذا أَمْ خَلَقُوا السَّماواتِ وَالْأَرْضَ بَلْ لا يُوقِنُونَ (36) أَمْ عِنْدَهُمْ خَزائِنُ رَبِّكَ أَمْ هُمُ الْمُصَيْطِرُونَ (37) أَمْ لَهُمْ سُلَّمٌ يَسْتَمِعُونَ فِيهِ فَلْيَأْتِ مُسْتَمِعُهُمْ بِسُلْطانٍ مُبِينٍ (38) ولا هذا كان لا بد من إذعانهم للخالق ، فلما ذا يكفرون به ويجعلون له شريكا ؟"},{"text":"أَمْ عِندَهُمْ خَزَآئِنُ رَبِّكَ أَمْ هُمُ ٱلْمُصَۣيْطِرُونَ","tafsir":"فهم شركاء لله ، والشريك لا يخضع لشريكه ، ( بَلْ ) ليس كل ذلك وهم يعلمون أنهم عبيد مربوبون وإنما ( لا يُوقِنُونَ ) فإن الانسياق وراء البرهان ـ دون الأهواء والتقاليد ـ لا يكون إلا لمن أراد التيقّن ، فنفي الإيقان عنهم باعتبار نفي آثاره ، كما يقال : لا عين لفلان إذ لم يستعمل عينه حتى سقط في بئر ، ويقال لا عقل له ، إذا لم يستعمل عقله."},{"text":"أَمْ لَهُمْ سُلَّمٌ يَسْتَمِعُونَ فِيهِ ۖ فَلْيَأْتِ مُسْتَمِعُهُم بِسُلْطَـٰنٍ مُّبِينٍ","tafsir":"فلا يرون أنفسهم بحاجة إلى الله ، ولذا لا يؤمنون به ولا برسوله ولا بكتابه ؟ ( أَمْ هُمُ الْمُصَيْطِرُونَ ) على الخزائن ، وإن تكن لهم فسيطرتهم على الخزائن توجب أن يزعموا غنائهم عن الإيمان ؟"},{"text":"أَمْ لَهُ ٱلْبَنَـٰتُ وَلَكُمُ ٱلْبَنُونَ","tafsir":"مرقاة يصعدون بسببها إلى السماء ( يَسْتَمِعُونَ فِيهِ ) إلى الوحي فلا يحتاجون إلى الرسول صلى‌الله‌عليه‌وآله‌وسلم لأنهم كالرسول يعرفون أمور السماء فإذ زعموا ذلك ، وقالوه عنادا ( فَلْيَأْتِ مُسْتَمِعُهُمْ ) من ادعى الاستماع ( بِسُلْطانٍ ) حجة ( مُبِينٍ ) واضحة على صدقه ، كأن يخبر عن الآتي ، كما يأتي النبي صلى‌الله‌عليه‌وآله‌وسلم بأخبار الغيب ، ولا يخفى أن في هذا احتجاج على منكر الله ، وعلى من جعل له شريكا ، وعلى من أَمْ لَهُ الْبَناتُ وَلَكُمُ الْبَنُونَ (39) أَمْ تَسْئَلُهُمْ أَجْراً فَهُمْ مِنْ مَغْرَمٍ مُثْقَلُونَ (40) أَمْ عِنْدَهُمُ الْغَيْبُ فَهُمْ يَكْتُبُونَ (41) أَمْ يُرِيدُونَ كَيْداً فَالَّذِينَ كَفَرُوا هُمُ الْمَكِيدُونَ (42) أنكر الرسول أو القرآن ، وعلى من أنكر البعث ، بأسلوب بلاغي رائع ، وباحتجاجات عقلية ، وعرفية يفهمها كل إنسان وإن لم يكن من أهل الخبرة والدقة."},{"text":"أَمْ تَسْـَٔلُهُمْ أَجْرًا فَهُم مِّن مَّغْرَمٍ مُّثْقَلُونَ","tafsir":"فقد كان جمع من كفار قريش يقولون إن الملائكة بنات الله ( وَلَكُمُ الْبَنُونَ ) البنون خاص بكم ؟ وبأي دليل تقولون هذا القول ؟."},{"text":"أَمْ عِندَهُمُ ٱلْغَيْبُ فَهُمْ يَكْتُبُونَ","tafsir":"يا رسول الله ( أَجْراً ) على الرسالة ( فَهُمْ مِنْ مَغْرَمٍ ) التزام غرم ( مُثْقَلُونَ ) يحملون الثقل ، ولذا لا يؤمنون بك فرارا من إعطاء المال ، وحيث لا تسألهم أجرا والدليل معك فلما ذا لا يؤمنون ؟"},{"text":"أَمْ يُرِيدُونَ كَيْدًا ۖ فَٱلَّذِينَ كَفَرُوا۟ هُمُ ٱلْمَكِيدُونَ","tafsir":"علم ( الْغَيْبُ فَهُمْ يَكْتُبُونَ ) ما أخذوه عن الغيب وبذلك علموا كذبك ولذا لا يؤمنون بك ؟"},{"text":"أَمْ لَهُمْ إِلَـٰهٌ غَيْرُ ٱللَّهِ ۚ سُبْحَـٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ","tafsir":"بك ، لا حجة لهم ، ولا عندهم الغيب ، وإنما يكيدون بك ليتخلصوا منك حتى لا تدعوهم إلى الهدى ، استثقالا عن الحق ، لكن فليعلموا أنهم لا يقدرون على الكيد بك ، وإنما كيدهم على أنفسهم ( فَالَّذِينَ كَفَرُوا هُمُ الْمَكِيدُونَ ) يعود وبال كيدهم عليهم ، كما قال ( وَمَكَرُوا وَمَكَرَ اللهُ وَاللهُ خَيْرُ الْماكِرِينَ ) (1) . ( 1) آل عمران : 55. أَمْ لَهُمْ إِلهٌ غَيْرُ اللهِ سُبْحانَ اللهِ عَمَّا يُشْرِكُونَ (43) وَإِنْ يَرَوْا كِسْفاً مِنَ السَّماءِ ساقِطاً يَقُولُوا سَحابٌ مَرْكُومٌ (44) فَذَرْهُمْ حَتَّى يُلاقُوا يَوْمَهُمُ الَّذِي فِيهِ يُصْعَقُونَ (45) يَوْمَ لا يُغْنِي عَنْهُمْ كَيْدُهُمْ شَيْئاً وَلا هُمْ يُنْصَرُونَ (46)"},{"text":"وَإِن يَرَوْا۟ كِسْفًا مِّنَ ٱلسَّمَآءِ سَاقِطًا يَقُولُوا۟ سَحَابٌ مَّرْكُومٌ","tafsir":"ولذا يشركون مع الله إلها غيره ؟ ( سُبْحانَ اللهِ ) الله منزه ( عَمَّا يُشْرِكُونَ ) إذ لا شريك له ، كما دلّ على ذلك العقل ، بالإضافة إلى أنهم لا دليل لهم على الشرك ، وفي هذه الآيات تفنيد لمزاعم الكفار ، والجامع بينها إنها كانت مزاعم باطلة رائجة بينهم. [45] وقد كان الكفار يتحدون الرسول صلى‌الله‌عليه‌وآله‌وسلم بأنه إن كان صادقا ، فليسقط عليهم قطعة من السماء لإهلاكهم ، مثل تحدي كل جاهل معاند ، وقد أجابهم القرآن بأنهم حتى إن رأوا ذلك عاندوا الحق ، كما هو شأن كل معاند ( وَإِنْ يَرَوْا كِسْفاً ) قطعة ( مِنَ السَّماءِ ) كأحجار الجو ، أو ما يزعمه سماء ، ( ساقِطاً يَقُولُوا ) من فرط عنادهم وطغيانهم ، هذا ( سَحابٌ مَرْكُومٌ ) تراكم وتجمع بعضه على بعض ، فلا فائدة في إتيانك يا رسول الله بهذه المعجزة."},{"text":"فَذَرْهُمْ حَتَّىٰ يُلَـٰقُوا۟ يَوْمَهُمُ ٱلَّذِى فِيهِ يُصْعَقُونَ","tafsir":""},{"text":"يَوْمَ لَا يُغْنِى عَنْهُمْ كَيْدُهُمْ شَيْـًٔا وَلَا هُمْ يُنصَرُونَ","tafsir":"فاتركهم بعد ما رأيت من عنادهم ( حَتَّى يُلاقُوا يَوْمَهُمُ الَّذِي فِيهِ يُصْعَقُونَ ) يموتون بأيديكم ، أو موتة طبيعية ، حتى يروا جزاءهم هناك."},{"text":"وَإِنَّ لِلَّذِينَ ظَلَمُوا۟ عَذَابًا دُونَ ذَٰلِكَ وَلَـٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ","tafsir":"في رد العذاب فإن عذاب الآخرة ليس كمشاكل الدنيا يمكن ردها بالكيد والأساليب الدنيوية ( وَلا هُمْ يُنْصَرُونَ ) كما ينصر بعضهم البعض في الدنيا ، فإن الآخرة ليس فيها وَإِنَّ لِلَّذِينَ ظَلَمُوا عَذاباً دُونَ ذلِكَ وَلكِنَّ أَكْثَرَهُمْ لا يَعْلَمُونَ (47) وَاصْبِرْ لِحُكْمِ رَبِّكَ فَإِنَّكَ بِأَعْيُنِنا وَسَبِّحْ بِحَمْدِ رَبِّكَ حِينَ تَقُومُ (48) وَمِنَ اللَّيْلِ فَسَبِّحْهُ وَإِدْبارَ النُّجُومِ (49) ناصر ينصر من أراد الله عذابه."},{"text":"وَٱصْبِرْ لِحُكْمِ رَبِّكَ فَإِنَّكَ بِأَعْيُنِنَا ۖ وَسَبِّحْ بِحَمْدِ رَبِّكَ حِينَ تَقُومُ","tafsir":"من هؤلاء الكفار ، جيء بهذا اللفظ ، للدلالة على اقتران الكفر بالظلم غالبا ، بل الكفر من أعظم الظلم بنفس الكافر ( عَذاباً دُونَ ذلِكَ ) قبل عذاب الآخرة ، وهو ما يشاهدونه في الدنيا من ثمرات أعمالهم ، فإن الظلم لا يثمر إلا العذاب ( وَلكِنَّ أَكْثَرَهُمْ لا يَعْلَمُونَ ) ذلك ، والحاصل أن كفرهم يعود عليهم بعذاب الدنيا وعذاب الآخرة."},{"text":"وَمِنَ ٱلَّيْلِ فَسَبِّحْهُ وَإِدْبَـٰرَ ٱلنُّجُومِ","tafsir":"الحكم الذي أعطاك ، فإن الرسول كان حاكما من قبل الله ( فَإِنَّكَ بِأَعْيُنِنا ) أي تحت حفظنا ورعايتنا ، والإتيان بجمع العين ، لبيان أنهم إن كانوا جماعة ضدك ، فإن أعينا أيضا تراقبك لحفظك ولئلا يمسوك بسوء ( وَسَبِّحْ بِحَمْدِ رَبِّكَ ) نزهه مع إثبات صفات الكمال له ـ كما تقدم مثله ـ ( حِينَ تَقُومُ ) في أول النهار واشكره على أن مضى ليلك بسلام."}]},"53":{"name":"النجم","verses":[{"text":"وَٱلنَّجْمِ إِذَا هَوَىٰ","tafsir":""},{"text":"مَا ضَلَّ صَاحِبُكُمْ وَمَا غَوَىٰ","tafsir":"قسما بالنجم ، والمنصرف جنس النجم ( إِذا هَوى ) نحو المغيب ، من وسط السماء ، أو من الأفق."},{"text":"وَمَا يَنطِقُ عَنِ ٱلْهَوَىٰٓ","tafsir":"ما عدل هو عن الطريق المستقيم ، ولعل وجه القسم بالنجم ، أن النبي صلى‌الله‌عليه‌وآله‌وسلم نجم معنوي في كل أحواله ، كما أن النجم نجم حتى في حال هويه ، ( وَما غَوى ) الناس في دعوته إلى الله ، بل هو مهتد في نفسه ودعوته للناس دعوة إلى الرشد."},{"text":"إِنْ هُوَ إِلَّا وَحْىٌ يُوحَىٰ","tafsir":"عن هوى النفس وميوله الشخصية كما كان الكافرون يقولون « تقوّله » ."},{"text":"عَلَّمَهُۥ شَدِيدُ ٱلْقُوَىٰ","tafsir":"ما ( هُوَ ) الذي نطق به من القرآن وسائر إخباره عن الله تعالى ( إِلَّا وَحْيٌ يُوحى ) إليه من جانب الله وهل الوحي وقتي ، أو مستمر وإنما جهاز الاستقبال وقتي مثله مثل نور الشمس المستمرة منذ أن خلقت ، وإنما إذا وجدت زجاجة مقعرة أخذته وأحرقت به ما ينعكس إليه النور منها ، فحالة الرسول صلى‌الله‌عليه‌وآله‌وسلم الخاصة تأخذ الوحي المناسب في الوقت المناسب ، احتمالان : وإن كان ظاهر الأدلة الأول."},{"text":"ذُو مِرَّةٍ فَٱسْتَوَىٰ","tafsir":"أي علم الرسول صلى‌الله‌عليه‌وآله‌وسلم بالوحي ( شَدِيدُ الْقُوى ) جبرئيل ، فإن للملك قوى كما للإنسان قوى ، وقوى الملك شديدة ، مثلا علمه كثير ، ولا ينسى ، وقدرته كثيرة ولا تضعف إلى غير ذلك ، وظاهر الآية بسياق الآيات الآتية أن المراد به جبرئيل عليه‌السلام . ذُو مِرَّةٍ فَاسْتَوى (6) وَهُوَ بِالْأُفُقِ الْأَعْلى (7) ثُمَّ دَنا فَتَدَلَّى (8) فَكانَ قابَ قَوْسَيْنِ أَوْ أَدْنى (9) فَأَوْحى إِلى عَبْدِهِ ما أَوْحى (10)"},{"text":"وَهُوَ بِٱلْأُفُقِ ٱلْأَعْلَىٰ","tafsir":"ذو قوة ، وأصل المرة خلط في العروق ، كالصفراء والسوداء ، وسمي مرة لقوة البدن به ، ثم استعملت في أصل القوة ، فكأنه قال مرة « قواه شديدة » ومرة « قوى بمجموعة » أو المراد بذي مرة حصانة في عقله ورأيه فالأول : لقواه المادية. والثاني : لقوته العقلية ، فلما أراد أن ينزل الوحي على الرسول صلى‌الله‌عليه‌وآله‌وسلم ( فَاسْتَوى ) استولى على الأرض لإتيان الوحي."},{"text":"ثُمَّ دَنَا فَتَدَلَّىٰ","tafsir":"جبرئيل عليه‌السلام ( بِالْأُفُقِ الْأَعْلى ) مكانه في أعالي السماوات."},{"text":"فَكَانَ قَابَ قَوْسَيْنِ أَوْ أَدْنَىٰ","tafsir":"جبرئيل إلى الرسول صلى‌الله‌عليه‌وآله‌وسلم ( فَتَدَلَّى ) في الهواء ، تدلي الدلو في البئر ، وأصل التدلي استرسال مع تعلق ، ولعل هذا التعبير باعتبار تعلق جبرئيل عليه‌السلام بالأعلى تعلقا."},{"text":"فَأَوْحَىٰٓ إِلَىٰ عَبْدِهِۦ مَآ أَوْحَىٰ","tafsir":"جبرئيل من محمد صلى‌الله‌عليه‌وآله‌وسلم ( قابَ قَوْسَيْنِ ) فإن قوسين إذا التصقت إحداهما بالأخرى يكون عرضهما مقدار ذراعين لأن « قاب » كل قوس مقدار ذراع تقريبا ، و « القاب » عبارة عن الفاصل بين رأسي القوس الواحد ، والمراد من هذه الآية ـ حسب الظاهر ـ إن قرب جبرئيل من رسول الله صلى‌الله‌عليه‌وآله‌وسلم كان بقدر ذراعين ( أَوْ أَدْنى ) ولعله كان يقترب ويبتعد ، كما هي عادة كل متكلّمين."},{"text":"مَا كَذَبَ ٱلْفُؤَادُ مَا رَأَىٰٓ","tafsir":"الله في هذه الحالة ( إِلى عَبْدِهِ ) الرسول صلى‌الله‌عليه‌وآله‌وسلم ( ما أَوْحى ) ما أراد وحيه ، أو المراد ، ب « أوحى » جبرئيل ، مثل ( قُلْ يَتَوَفَّاكُمْ مَلَكُ ما كَذَبَ الْفُؤادُ ما رَأى (11) أَ فَتُمارُونَهُ عَلى ما يَرى (12) وَلَقَدْ رَآهُ نَزْلَةً أُخْرى (13) عِنْدَ سِدْرَةِ الْمُنْتَهى (14) عِنْدَها جَنَّةُ الْمَأْوى (15) الْمَوْتِ ) (1) أما الضمير في عبده راجع إلى الله سبحانه ، وفي تفسير الآية ذكر مصاديق وتأويلات لا تنافي ظاهرها الذي ذكرناه."},{"text":"أَفَتُمَـٰرُونَهُۥ عَلَىٰ مَا يَرَىٰ","tafsir":"فؤاد رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( ما رَأى ) من جبرئيل وسمع من الوحي ، إذ قد يكذب الفؤاد الحواس ، كأن يرى الإنسان الشمس والقمر صغيرين ، أو ماء البحر أسود ، لكن القلب يقول ليس كما رأيت ، فالرسول صلى‌الله‌عليه‌وآله‌وسلم رأى جبرئيل بعينه وعرف صدق رؤيته بقلبه."},{"text":"وَلَقَدْ رَءَاهُ نَزْلَةً أُخْرَىٰ","tafsir":"أي أيها الكفار هل تجادلون محمد صلى‌الله‌عليه‌وآله‌وسلم ( عَلى ما يَرى ) ما رآه فتقولون له : قد اشتبهت ولم يكن جبرئيل ؟ ولعل الإتيان ب « يرى » بصيغة المستقبل ، لاستمرار علم الرسول صلى‌الله‌عليه‌وآله‌وسلم إلى وقت الكلام ، بأن ما رآه كان صدقا ، لا خيالا. [14] وهل يمكن أن يكون الرسول صلى‌الله‌عليه‌وآله‌وسلم قد اشتبه ( وَ ) الحال أن الرسول صلى‌الله‌عليه‌وآله‌وسلم ( لَقَدْ رَآهُ ) رأى جبرئيل ( نَزْلَةً أُخْرى ) حين نزل بالوحي إليه مرة ثانية ، والاشتباه لا يمكن مرتين. [15] وكانت رؤيته صلى‌الله‌عليه‌وآله‌وسلم الثانية لجبرئيل عليه‌السلام ( عِنْدَ سِدْرَةِ الْمُنْتَهى ) « المنتهى » مضاف إليه ، لعل المراد انتهاء عالم الدنيا إلى هناك بقرينة."},{"text":"عِندَ سِدْرَةِ ٱلْمُنتَهَىٰ","tafsir":""},{"text":"عِندَهَا جَنَّةُ ٱلْمَأْوَىٰٓ","tafsir":""},{"text":"إِذْ يَغْشَى ٱلسِّدْرَةَ مَا يَغْشَىٰ","tafsir":"أي عند تلك السدرة ( جَنَّةُ الْمَأْوى ) التي يأوي إليها ( 1) السجدة : 12. إِذْ يَغْشَى السِّدْرَةَ ما يَغْشى (16) ما زاغَ الْبَصَرُ وَما طَغى (17) لَقَدْ رَأى مِنْ آياتِ رَبِّهِ الْكُبْرى (18) أَ فَرَأَيْتُمُ اللاَّتَ وَالْعُزَّى (19) المؤمنون الصالحون."},{"text":"مَا زَاغَ ٱلْبَصَرُ وَمَا طَغَىٰ","tafsir":"غشيه بمعنى أحاط به واستولى عليه ( ما يَغْشى ) مما لا يعلمه إلا الله تعالى ولعلها باعتبار كونها الحدّ الفاصل بين عالم الدنيا وعالم الآخرة ، يكون مهبط الأملاك من الجنة إلى السماوات والأرض ، ومصعد أرواح المؤمنين والملائكة الصاعدة من الأرضين والسماوات إلى طرف الجنة. [18] ولا يقول الكفار لعلّه اشتبه الرسول صلى‌الله‌عليه‌وآله‌وسلم هذه المرة أيضا ، لأنه ( ما زاغَ ) لم يمل ( الْبَصَرُ ) بصر رسول الله ، بأن رأى غير جبرئيل فزعم ( وَما طَغى ) بأن لم يكن شيء فيزعمه شيئا كما في من يرى السراب فيزعمه شيئا وهو ليس بشيء ، ثم لا يخفى أن رؤية الرسول صلى‌الله‌عليه‌وآله‌وسلم لجبرئيل مرتين ، إنما يراد به أنه رآه بصورته الواقعية ، كما ورد بذلك النص والتفاسير (1) ، وإما بغير صورته الواقعية ، كصورة « دحية » فقد رآه صلى‌الله‌عليه‌وآله‌وسلم مرات عديدة."},{"text":"لَقَدْ رَأَىٰ مِنْ ءَايَـٰتِ رَبِّهِ ٱلْكُبْرَىٰٓ","tafsir":""},{"text":"أَفَرَءَيْتُمُ ٱللَّـٰتَ وَٱلْعُزَّىٰ","tafsir":"الرسول صلى‌الله‌عليه‌وآله‌وسلم عند سدرة المنتهى ( مِنْ آياتِ رَبِّهِ الْكُبْرى ) أي الآيات العظام التي كانت حول شجرة السدرة. [20] هل الله وما شاهده الرسول صلى‌الله‌عليه‌وآله‌وسلم من آيات الله ، يقاس بما أنتم عاكفون عليها من الأصنام ؟ ( أَ فَرَأَيْتُمُ اللَّاتَ وَالْعُزَّى ) وهما صنمان كان ( 1) الاحتجاج : ج 1 ص 243. وَمَناةَ الثَّالِثَةَ الْأُخْرى (20) أَ لَكُمُ الذَّكَرُ وَلَهُ الْأُنْثى (21) تِلْكَ إِذاً قِسْمَةٌ ضِيزى (22) إِنْ هِيَ إِلاَّ أَسْماءٌ سَمَّيْتُمُوها أَنْتُمْ وَآباؤُكُمْ ما أَنْزَلَ اللهُ بِها مِنْ سُلْطانٍ يعبدهما قريش."},{"text":"وَمَنَوٰةَ ٱلثَّالِثَةَ ٱلْأُخْرَىٰٓ","tafsir":""},{"text":"أَلَكُمُ ٱلذَّكَرُ وَلَهُ ٱلْأُنثَىٰ","tafsir":"الصنم ( الثَّالِثَةَ الْأُخْرى ) ولعلها أخرى في المرتبة عندهم ؟ أقول : وحذف الجواب لزيادة الاستهجان ، فهو كما يقال « لزيد مليون دينار » ثم يقال أرأيتم كم لعمرو من الدنانير ؟ « فيما كان له ثلاثة دنانير مثلا » فإن قوله : أ رأيت ، يراد به الاستهجان ، وبيان عدم المقايسة بين الأمرين. [22] ثم استهجن القرآن كلاما أخرا للمشركين ، وهو قولهم أن الملائكة بنات الله فقال ( أَ لَكُمُ الذَّكَرُ وَلَهُ ) سبحانه ( الْأُنْثى ) فقد كانوا يزعمون بأنهم مخصصون بالأولاد الذكور ، ولا ولد ذكر الله تعالى ، ويحتمل أن يراد أنكم تكرهون الإناث ، فكيف جعلتم الأصنام الثلاثة « وكانوا يزعمون أنهم إناث » شركاء الله تعالى."},{"text":"تِلْكَ إِذًا قِسْمَةٌ ضِيزَىٰٓ","tafsir":""},{"text":"إِنْ هِىَ إِلَّآ أَسْمَآءٌ سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلْطَـٰنٍ ۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَمَا تَهْوَى ٱلْأَنفُسُ ۖ وَلَقَدْ جَآءَهُم مِّن رَّبِّهِمُ ٱلْهُدَىٰٓ","tafsir":"القسمة بينكم ف « لكم الذكر » وبين الله « وله الأنثى » ( إِذاً ) إذا كان كما زعمتم ( قِسْمَةٌ ضِيزى ) جائرة ، من ضاز يضيز ، إذا جار."},{"text":"أَمْ لِلْإِنسَـٰنِ مَا تَمَنَّىٰ","tafsir":"ما تلك الأصنام الثلاثة ( إِلَّا أَسْماءٌ ) أي تسميتها بالألوهية اسم مجرد لا حقيقة تحت هذا الاسم ف « هي » محل ، أطلق ، وأريد به « الحال » لأن « الاسم » حال ، و « الصنم » محل ( سَمَّيْتُمُوها ) مجرد تسمية ( أَنْتُمْ وَآباؤُكُمْ ) من قبل ، وإلا فهل الأصنام آلهة ؟ ( ما أَنْزَلَ اللهُ بِها مِنْ سُلْطانٍ ) من حجة وبرهان ، وإنما هوى أنفسهم مع تلك إِنْ يَتَّبِعُونَ إِلاَّ الظَّنَّ وَما تَهْوَى الْأَنْفُسُ وَلَقَدْ جاءَهُمْ مِنْ رَبِّهِمُ الْهُدى (23) أَمْ لِلْإِنْسانِ ما تَمَنَّى (24) فَلِلَّهِ الْآخِرَةُ وَالْأُولى (25) وَكَمْ مِنْ مَلَكٍ فِي السَّماواتِ لا تُغْنِي شَفاعَتُهُمْ شَيْئاً الأصنام ثم ظنوا أنها آلهة ، فلا دليل من العقل ولا من الشرع عليها ( إِنْ ) ما ( يَتَّبِعُونَ إِلَّا الظَّنَ ) بأنها آلهة ( وَما تَهْوَى الْأَنْفُسُ ) ما تشتهيه أنفسهم ( وَلَقَدْ جاءَهُمْ مِنْ رَبِّهِمُ الْهُدى ) الرسول والكتاب المطابقان للعقل والفطرة فتركوهما واتبعوا أهواءهم الباطلة في القول بأن الأصنام آلهة."},{"text":"فَلِلَّهِ ٱلْـَٔاخِرَةُ وَٱلْأُولَىٰ","tafsir":"استفهام إنكاري أي ليس للإنسان ما يتمناه ، فهؤلاء يتمنون صحة عقيدتهم ويتمنون أن تشفع الأصنام لهم ، لكن هذا التمني لا يتحقق."},{"text":"۞ وَكَم مِّن مَّلَكٍ فِى ٱلسَّمَـٰوَٰتِ لَا تُغْنِى شَفَـٰعَتُهُمْ شَيْـًٔا إِلَّا مِنۢ بَعْدِ أَن يَأْذَنَ ٱللَّهُ لِمَن يَشَآءُ وَيَرْضَىٰٓ","tafsir":"بيده كل شيء فهو الإله وهو الشفيع ( قُلْ لِلَّهِ الشَّفاعَةُ جَمِيعاً ) (1) . [27] إنهم يرجون الشفاعة من الأصنام بينما الملائكة لا تقدر على الشفاعة إلا بعد إذن الله ( وَكَمْ مِنْ مَلَكٍ فِي السَّماواتِ ) فهو مع كونه ملكا ، ومع كونه في السماوات قريبا من رحمة الله ( لا تُغْنِي ) لا تفيد ( شَفاعَتُهُمْ شَيْئاً ) أي أنهم على تقدير أن يشفعوا لا تفيد شفاعتهم و « كم » لا مفهوم له ، حتى يكون هناك « ملك » تغني شفاعته ، ولعل الإتيان به لإفادة أنه إذا كان كثير من الملائكة كذلك ، فكيف بالأصنام ؟ ولا حاجة في إسقاط الأصنام ( 1) الزمر : 45. إِلاَّ مِنْ بَعْدِ أَنْ يَأْذَنَ اللهُ لِمَنْ يَشاءُ وَيَرْضى (26) إِنَّ الَّذِينَ لا يُؤْمِنُونَ بِالْآخِرَةِ لَيُسَمُّونَ الْمَلائِكَةَ تَسْمِيَةَ الْأُنْثى (27) وَما لَهُمْ بِهِ مِنْ عِلْمٍ إِنْ يَتَّبِعُونَ إِلاَّ الظَّنَّ وَإِنَّ الظَّنَّ لا يُغْنِي مِنَ الْحَقِّ شَيْئاً (28) فَأَعْرِضْ عَنْ مَنْ تَوَلَّى عَنْ ذِكْرِنا وَلَمْ يُرِدْ إِلاَّ الْحَياةَ الدُّنْيا (29) عن الشفاعة القول بأن « كل الملائكة كذلك » ( إِلَّا مِنْ بَعْدِ أَنْ يَأْذَنَ اللهُ ) في الشفاعة ( لِمَنْ يَشاءُ ) من الملائكة أن يشفع ومن الناس أن يشفع له ( وَيَرْضى ) ويراه أهلا لذلك : شافعا ومشفوعا ، والرضا وإن كان قبل الإذن إلا أن ملاحظة رؤوس الآي أورث تأخيره ،"},{"text":"إِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ لَيُسَمُّونَ ٱلْمَلَـٰٓئِكَةَ تَسْمِيَةَ ٱلْأُنثَىٰ","tafsir":""},{"text":"وَمَا لَهُم بِهِۦ مِنْ عِلْمٍ ۖ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ ۖ وَإِنَّ ٱلظَّنَّ لَا يُغْنِى مِنَ ٱلْحَقِّ شَيْـًٔا","tafsir":"الكفار ( الَّذِينَ لا يُؤْمِنُونَ بِالْآخِرَةِ ) وذلك يلازم عدم إيمانهم بما جاء عن الله ( لَيُسَمُّونَ الْمَلائِكَةَ تَسْمِيَةَ الْأُنْثى ) فإنهم حيث قالوا الملائكة بنات الله سموا كل ملك بنتا."},{"text":"فَأَعْرِضْ عَن مَّن تَوَلَّىٰ عَن ذِكْرِنَا وَلَمْ يُرِدْ إِلَّا ٱلْحَيَوٰةَ ٱلدُّنْيَا","tafsir":"الحال ( ما لَهُمْ بِهِ ) بما يقولون ( مِنْ عِلْمٍ ) أي لا علم لهم بأن الملائكة أنثى ( إِنْ ) ما ( يَتَّبِعُونَ إِلَّا الظَّنَ ) فإنهم يظنون أن الملائكة بنات ( وَإِنَّ الظَّنَّ لا يُغْنِي ) لا يفيد ( مِنَ الْحَقِّ شَيْئاً ) إذ لا برهان للظن ، وما لا برهان له ليس مطابقا للواقع ، فإن كل مطابق للواقع له برهان."},{"text":"ذَٰلِكَ مَبْلَغُهُم مِّنَ ٱلْعِلْمِ ۚ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِمَنِ ٱهْتَدَىٰ","tafsir":"يا رسول الله ( عَنْ مَنْ تَوَلَّى عَنْ ذِكْرِنا ) إذ لا يفيد معه التذكير ! لأنه معاند ( وَلَمْ يُرِدْ إِلَّا الْحَياةَ الدُّنْيا ) فكل سعيه وعمله للدنيا ، ذلِكَ مَبْلَغُهُمْ مِنَ الْعِلْمِ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَنْ ضَلَّ عَنْ سَبِيلِهِ وَهُوَ أَعْلَمُ بِمَنِ اهْتَدى (30) وَلِلَّهِ ما فِي السَّماواتِ وَما فِي الْأَرْضِ لِيَجْزِيَ الَّذِينَ أَساؤُا بِما عَمِلُوا وَيَجْزِيَ الَّذِينَ أَحْسَنُوا بِالْحُسْنَى (31) الَّذِينَ يَجْتَنِبُونَ كَبائِرَ الْإِثْمِ وَالْفَواحِشَ ولا يعتقد بالآخرة حتى يعمل لها ، فهو منكر للتوحيد ، ومنكر للمعاد."},{"text":"وَلِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ لِيَجْزِىَ ٱلَّذِينَ أَسَـٰٓـُٔوا۟ بِمَا عَمِلُوا۟ وَيَجْزِىَ ٱلَّذِينَ أَحْسَنُوا۟ بِٱلْحُسْنَى","tafsir":"انحصار فكرهم في الدنيا ، من دون نفوذ علمهم إلى المبدأ ولا إلى المعاد ( مَبْلَغُهُمْ مِنَ الْعِلْمِ ) قدر بلوغ علمهم فهو علم ضيّق محدود منحرف ، فلا تتعب نفسك يا رسول الله مع هؤلاء فإن الله يعلم حالهم وسوف يجازيهم ( إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَنْ ضَلَّ عَنْ سَبِيلِهِ ) أي أنفذ علما فيعلم خصوصياتهم وكل دقائقهم ( وَهُوَ أَعْلَمُ بِمَنِ اهْتَدى ) فيجازي كلا حسب عقيدته وعمله."},{"text":"ٱلَّذِينَ يَجْتَنِبُونَ كَبَـٰٓئِرَ ٱلْإِثْمِ وَٱلْفَوَٰحِشَ إِلَّا ٱللَّمَمَ ۚ إِنَّ رَبَّكَ وَٰسِعُ ٱلْمَغْفِرَةِ ۚ هُوَ أَعْلَمُ بِكُمْ إِذْ أَنشَأَكُم مِّنَ ٱلْأَرْضِ وَإِذْ أَنتُمْ أَجِنَّةٌ فِى بُطُونِ أُمَّهَـٰتِكُمْ ۖ فَلَا تُزَكُّوٓا۟ أَنفُسَكُمْ ۖ هُوَ أَعْلَمُ بِمَنِ ٱتَّقَىٰٓ","tafsir":"أي الذي ( فِي السَّماواتِ وَما ) أي الذي ( فِي الْأَرْضِ ) أي كل شيء فيهما ملكا وخلقا ( لِيَجْزِيَ ) الله ( الَّذِينَ أَساؤُا بِما عَمِلُوا ) والعمل يشمل عمل القلب أيضا لأن الاعتقاد عقد القلب على شيء خاص ، و « اللام » للعاقبة ، لا للعلّة ، مثله ، مثل ( لِيَكُونَ لَهُمْ عَدُوًّا ) (1) ( وَيَجْزِيَ الَّذِينَ أَحْسَنُوا ) بالمثوبة الحسنى في الدنيا والآخرة. [33] ومن هم الذين أحسنوا ؟ هم ( الَّذِينَ يَجْتَنِبُونَ كَبائِرَ الْإِثْمِ ) الآثام الكبيرة والتي منها الكفر والشرك وعدم الإيمان بالرسول وبما جاء به الرسول وعدم الإيمان بالمعاد ( وَالْفَواحِشَ ) التي إثمها يتعدى إلى ( 1) القصص : 9. إِلاَّ اللَّمَمَ إِنَّ رَبَّكَ واسِعُ الْمَغْفِرَةِ هُوَ أَعْلَمُ بِكُمْ إِذْ أَنْشَأَكُمْ مِنَ الْأَرْضِ وَإِذْ أَنْتُمْ أَجِنَّةٌ فِي بُطُونِ أُمَّهاتِكُمْ فَلا تُزَكُّوا أَنْفُسَكُمْ هُوَ أَعْلَمُ بِمَنِ اتَّقى (32) الآخرين ، من فحش إذا تعدى عمله الآثم إلى الآخرين ( إِلَّا اللَّمَمَ ) أي الذي يلمّ بالإنسان ويرد عليه مما لا علاج من وروده غالبا ، وهي الصغائر وهي الصغائر مثل كلمة نابية ، أو ضحكة غير جائزة أو نظرة محرمة أو ما شابه ذلك ، والاستثناء منقطع لدفع توهم أن كل عصيان كبيرة ، حيث إنها معصية لإله عظيم ( إِنَّ رَبَّكَ واسِعُ الْمَغْفِرَةِ ) فيغفر للّمم قطعا ، بعد أن كان يغفر لكثير من الكبائر لمن يشاء ( هُوَ أَعْلَمُ بِكُمْ ) حتى من أنفسكم فمن عمل صالحا يعرفه ومن عمل فاسدا يعرفه ( إِذْ أَنْشَأَكُمْ مِنَ الْأَرْضِ ) فإن علمه شامل لزمان تكوينكم من الأرض حيث إن الإنسان تراب ثم ينقلب ، نباتا ، ثم ينقلب حيوانا ثم النبات والحيوان ينقلب إلى طعام يأكله الأبوان فيصير دما ثم منيّا ( وَإِذْ أَنْتُمْ أَجِنَّةٌ ) جمع جنين ( فِي بُطُونِ أُمَّهاتِكُمْ ) وهذه أول مرحلة إنسانية ، فيعلم بكم من ذلك الحين إلى اليوم ( فَلا تُزَكُّوا أَنْفُسَكُمْ ) لا يغرنكم أعمالكم الصالحة ، كما يقع فيه بعض المؤمنين غير المتأدبين ، فيزكي نفسه إنه صام وصلى وأنفق وفعل الخير ، فإنه غرور يوجب سقوط النفس عن الرفعة عند الله وعند الناس ( هُوَ ) سبحانه ( أَعْلَمُ بِمَنِ اتَّقى ) فعلى المؤمن ، لا يكون مفرّطا بعمل الفواحش ، ولا مفرطا يزكي نفسه ، فإن التزكية للنفس قبيح ، ولله أقبح لأنه أعلم بالإنسان من حال كونه ترابا إلى حال تقيّا ، حتى من نفسه. [34] وإذا عرفنا أحوال المتقين الذين يجتنبون كبائر الإثم والفواحش إلا أَ فَرَأَيْتَ الَّذِي تَوَلَّى (33) وَأَعْطى قَلِيلاً وَأَكْدى (34) أَ عِنْدَهُ عِلْمُ الْغَيْبِ فَهُوَ يَرى (35) أَمْ لَمْ يُنَبَّأْ بِما فِي صُحُفِ مُوسى (36) وَإِبْراهِيمَ الَّذِي وَفَّى (37) اللمم فلنعرف أحوال غيرهم ( أَ فَرَأَيْتَ ) في قبال ذلك المتقي ( الَّذِي تَوَلَّى ) عن الحق وأعرض عنه وإن آمن به."},{"text":"أَفَرَءَيْتَ ٱلَّذِى تَوَلَّىٰ","tafsir":""},{"text":"وَأَعْطَىٰ قَلِيلًا وَأَكْدَىٰٓ","tafsir":""},{"text":"أَعِندَهُۥ عِلْمُ ٱلْغَيْبِ فَهُوَ يَرَىٰٓ","tafsir":"مالا ( قَلِيلاً ) كما هو شأن كثير من الناس حيث يظهرون الإيمان لكنهم لا يلتزمون بموازينه ، وبالأخص لا يدفعون المال المفروض عليهم إطلاقا أو يعطون شيئا قليلا ( وَأَكْدى ) أي قطع العطاء وأمسك يده عن الإنفاق ، لغلبة حالة البخل عليه ، ومن طبيعة أمثال هؤلاء الناس ، أنهم يلقون تبعة ذنوبهم على غيرهم ، فإذا قلت له لماذا تعصي ؟ قال ذنب المبلغين الذين لا يبلغون كاملا ، ثم أن الله يغفر لي ، وما أشبه من الكلمات المتعارفة عند البخلاء والعصاة ، وفي التفاسير أنّ الآيات نزلت في عثمان في قصة (1) ، ومن المعلوم أنه من باب المصداق."},{"text":"أَمْ لَمْ يُنَبَّأْ بِمَا فِى صُحُفِ مُوسَىٰ","tafsir":""},{"text":"وَإِبْرَٰهِيمَ ٱلَّذِى وَفَّىٰٓ","tafsir":"ألم يخبر ( بِما فِي صُحُفِ مُوسى ) ."},{"text":"أَلَّا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ","tafsir":"بما في صحف ( إِبْراهِيمَ الَّذِي وَفَّى ) كان وفيّا بكل ما تعهد من قبل الله سبحانه ، و « وفّى » بالتشديد مبالغة في الوفاء « وفيه تعريض أن هذا المؤمن الذي أعطى قليلا .. . إلى آخره » لم يوفي بما شرط على ( 1) مجمع البيان : ج 9 ص 298. أَلاَّ تَزِرُ وازِرَةٌ وِزْرَ أُخْرى (38) وَأَنْ لَيْسَ لِلْإِنْسانِ إِلاَّ ما سَعى (39) وَأَنَّ سَعْيَهُ سَوْفَ يُرى (40) ثُمَّ يُجْزاهُ الْجَزاءَ الْأَوْفى (41) وَأَنَّ إِلى رَبِّكَ الْمُنْتَهى (42) وَأَنَّهُ هُوَ أَضْحَكَ وَأَبْكى (43) نفسه من الإطاعة في كل الأوامر."},{"text":"وَأَن لَّيْسَ لِلْإِنسَـٰنِ إِلَّا مَا سَعَىٰ","tafsir":"لا تحمل ( وازِرَةٌ ) نفس حاملة ( وِزْرَ ) حمل نفس ( أُخْرى ) فكل إنسان ذنبه على نفسه ، لا كما زعم هذا البخيل من أن ذنبه على غيره."},{"text":"وَأَنَّ سَعْيَهُۥ سَوْفَ يُرَىٰ","tafsir":"؟ فلم يزعم أن إعطائه القليل كاف عن الإعطاء الذي أمر به فكما لا يؤخذ أحد بذنب الغير كذلك لا يثاب أحد بأكثر مما عمل."},{"text":"ثُمَّ يُجْزَىٰهُ ٱلْجَزَآءَ ٱلْأَوْفَىٰ","tafsir":"يراه بنفسه بدار الدنيا جزاء بالمدح أو بغير ذلك ، فإن الدنيا قبل الآخرة دار المكافآت « ولا يجتني الجاني من الشوك العنب » ."},{"text":"وَأَنَّ إِلَىٰ رَبِّكَ ٱلْمُنتَهَىٰ","tafsir":"أي يجزي العبد سعيه ( الْجَزاءَ الْأَوْفى ) الأوفر وذلك في الآخرة. [43] وليعلم الناس أن الله هو مبدأ الأشياء وكل الأشياء تنتهي إليه وكل الأمور بيده ، ولذا يجب عليهم شكره ، وطاعته ، كما يجب عليهم أن يخافوا من عقابه وعذابه ( وَأَنَّ إِلى رَبِّكَ الْمُنْتَهى ) انتهاء كل شيء ، ومعنى « إلى » إلى جزائه وثوابه وعقابه."},{"text":"وَأَنَّهُۥ هُوَ أَضْحَكَ وَأَبْكَىٰ","tafsir":""},{"text":"وَأَنَّهُۥ هُوَ أَمَاتَ وَأَحْيَا","tafsir":"سبحانه ( أَضْحَكَ وَأَبْكى ) فقد خلق في الإنسان قوتهما وَأَنَّهُ هُوَ أَماتَ وَأَحْيا (44) وَأَنَّهُ خَلَقَ الزَّوْجَيْنِ الذَّكَرَ وَالْأُنْثى (45) مِنْ نُطْفَةٍ إِذا تُمْنى (46) وَأَنَّ عَلَيْهِ النَّشْأَةَ الْأُخْرى (47) وَأَنَّهُ هُوَ أَغْنى وَأَقْنى (48) وَأَنَّهُ هُوَ رَبُّ الشِّعْرى (49) كما خلق وقدر ما يسبب البكاء والضحك ، والضحك والبكاء ليس خاصا بالإنسان بل كل شيء له ضحك وبكاء ، قال الشاعر : إن فصل الربيع فصل جميل تضحك الأرض من بكاء السماء ذهب حيثما ذهبنا ودرّ حيث درنا وفضة في الفضاء"},{"text":"وَأَنَّهُۥ خَلَقَ ٱلزَّوْجَيْنِ ٱلذَّكَرَ وَٱلْأُنثَىٰ","tafsir":"سبحانه ( أَماتَ وَأَحْيا ) حتى أنه إذا قتل الإنسان إنسانا فإن روحه بيد الله ، ولذا لا يموت الإنسان في جهنم."},{"text":"مِن نُّطْفَةٍ إِذَا تُمْنَىٰ","tafsir":"من كل شيء ( الذَّكَرَ وَالْأُنْثى ) وعدم ذكر الخنثى إما لشذوذه ، أو لأنه في الحقيقة إما ذكر أو أنثى. [47] خلقهما ( مِنْ نُطْفَةٍ ) هي الماء القليل ( إِذا تُمْنى ) تدفق في الرحم."},{"text":"وَأَنَّ عَلَيْهِ ٱلنَّشْأَةَ ٱلْأُخْرَىٰ","tafsir":""},{"text":"وَأَنَّهُۥ هُوَ أَغْنَىٰ وَأَقْنَىٰ","tafsir":"سبحانه ( النَّشْأَةَ ) الإنشاء بعد الموت ( الْأُخْرى ) فكما بدأ يقدر على الإعادة."},{"text":"وَأَنَّهُۥ هُوَ رَبُّ ٱلشِّعْرَىٰ","tafsir":"الأغنياء بخلق وسائل الغنى ( وَأَقْنى ) أعطى المال الذي يدّخر للقنية أي الإبقاء ، فالمال المتحرك الموجب للغنى ، والمال الثابت كلاهما من عنده تعالى."},{"text":"وَأَنَّهُۥٓ أَهْلَكَ عَادًا ٱلْأُولَىٰ","tafsir":"تعالى ( رَبُّ الشِّعْرى ) نجم في السماء يطلع آخر الليل ، وَأَنَّهُ أَهْلَكَ عاداً الْأُولى (50) وَثَمُودَ فَما أَبْقى (51) وَقَوْمَ نُوحٍ مِنْ قَبْلُ إِنَّهُمْ كانُوا هُمْ أَظْلَمَ وَأَطْغى (52) وَالْمُؤْتَفِكَةَ أَهْوى (53) فَغَشَّاها ما غَشَّى (54) فَبِأَيِّ آلاءِ رَبِّكَ تَتَمارى (55) كان جماعة من العرب يعبدونه."},{"text":"وَثَمُودَا۟ فَمَآ أَبْقَىٰ","tafsir":"أي قبيلة عاد ( الْأُولى ) قوم هود عليه‌السلام وهناك عاد ثانية عاد إرم ذات العماد."},{"text":"وَقَوْمَ نُوحٍ مِّن قَبْلُ ۖ إِنَّهُمْ كَانُوا۟ هُمْ أَظْلَمَ وَأَطْغَىٰ","tafsir":"أهلك ( ثَمُودَ ) قوم صالح ( فَما أَبْقى ) أحدا من الفريقين ، حيث عصوا وعتوا وكان جزاؤهم العذاب."},{"text":"وَٱلْمُؤْتَفِكَةَ أَهْوَىٰ","tafsir":"أهلك ( قَوْمَ نُوحٍ مِنْ قَبْلُ ) قبل عاد وثمود ( إِنَّهُمْ كانُوا هُمْ أَظْلَمَ ) أكثر ظلما ( وَأَطْغى ) أكثر طغيانا فقد ورد أنهم كانوا يضربون نوحا عليه‌السلام حتى يبقى ليس به حراك ، فهم ظالمون لأنفسهم طاغون على غيرهم وقد دعاهم ألف سنة إلا خمسين عاما فلم ينفع فيهم."},{"text":"فَغَشَّىٰهَا مَا غَشَّىٰ","tafsir":"وهي قرى قوم لوط عليه‌السلام التي ائتفكت بأهلها أي انقلبت ( أَهْوى ) بها وقلّبها بعد أن رفعها."},{"text":"فَبِأَىِّ ءَالَآءِ رَبِّكَ تَتَمَارَىٰ","tafsir":"أحاط بتلك القرى من العذاب ( ما غَشَّى ) الشيء الذي غشاها من أصناف العذاب الذي لا يوصف. [56] وبعد كل هذه العذابات التي تعلم بها ، مما أصاب العصاة ( فَبِأَيِّ آلاءِ ) نعم ( رَبِّكَ ) يا أيها الإنسان ( تَتَمارى ) تتشكك ، أليس وجود الأنبياء نعمة ؟ أليس إنزال الكتب نعمة ، أليس إرشاد العقل إلى الصحيح والباطل نعمة ؟ وهل شك في هذه النعم التي من أخذ بمقتضاها سعد ، ومن ترك مقتضاها شقي وعذب ، حتى إنك تشك هذا نَذِيرٌ مِنَ النُّذُرِ الْأُولى (56) أَزِفَتِ الْآزِفَةُ (57) لَيْسَ لَها مِنْ دُونِ اللهِ كاشِفَةٌ (58) أَفَمِنْ هذَا الْحَدِيثِ تَعْجَبُونَ (59) وتعصي وتترك الأوامر."},{"text":"هَـٰذَا نَذِيرٌ مِّنَ ٱلنُّذُرِ ٱلْأُولَىٰٓ","tafsir":""},{"text":"أَزِفَتِ ٱلْـَٔازِفَةُ","tafsir":"القرآن ( نَذِيرٌ ) ينذركم من عذاب الله لمن عصي ( مِنَ النُّذُرِ الْأُولى ) من جنس الإنذارات السابقة التي بعثنا بها إلى الأمم السابقين ، ومن المحتمل أن يكون المراد بهذا الرسول صلى‌الله‌عليه‌وآله‌وسلم فهو نذير من جنس المنذرين « الرسل » السابقين. [58] لقد ( أَزِفَتِ ) قربت ( الْآزِفَةُ ) القيامة التي هي قريبة إلى كل من جاء إلى دار الدنيا ، فإن الإنسان خلق جسمه الذي هو من التراب ، قبل مئات الألوف من السنوات ، وقد خلق الله الأرواح قبل الأجساد بألفي عام ، فإذا جاء إلى دار الدنيا فقد قرب موته ، وإذا مات الإنسان قامت قيامته ، أو المراد القيامة الحقيقية ، لأن أكثر عمر الدنيا قد انقضى ـ كما دل على ذلك الآثار والعلم الحديث ـ ."},{"text":"لَيْسَ لَهَا مِن دُونِ ٱللَّهِ كَاشِفَةٌ","tafsir":""},{"text":"أَفَمِنْ هَـٰذَا ٱلْحَدِيثِ تَعْجَبُونَ","tafsir":"للآزفة ( مِنْ دُونِ اللهِ ) أحد غير الله ( كاشِفَةٌ ) نفس قادرة على كشفها والإتيان بها ، فإن القيامة شيء مخفي ، فإذا أقامها الله سبحانه فقد كشفها ، والمراد الكناية عن أن القيامة بيد الله تعالى. [60] إذن فاللازم على هؤلاء من خوف عقاب الدنيا ـ كما في الآيات السابقة ـ ومن خوف عقاب الآخرة ـ كما في هاتين الآيتين ـ أن يؤمنوا ويخافوا ويعملوا صالحا ، ولكنهم سادرون في غيّهم ( أَ فَمِنْ هذَا الْحَدِيثِ ) حديث التوحيد والنبوة والمعاد مما جاء به النبي صلى‌الله‌عليه‌وآله‌وسلم ( تَعْجَبُونَ ) ؟ وقد كان اللازم أن لا تعجبوا ، لأنه قد قامت الحجة عليه. وَتَضْحَكُونَ وَلا تَبْكُونَ (60) وَأَنْتُمْ سامِدُونَ (61) فَاسْجُدُوا لِلَّهِ وَاعْبُدُوا (62)"},{"text":"وَتَضْحَكُونَ وَلَا تَبْكُونَ","tafsir":""},{"text":"وَأَنتُمْ سَـٰمِدُونَ","tafsir":"استهزاء ( وَلا تَبْكُونَ ) ندما وحزنا على ما سلف منكم من الكفر والآثام ، وحزنا على ما يأتي من عقاب الدنيا والآخرة."},{"text":"فَٱسْجُدُوا۟ لِلَّهِ وَٱعْبُدُوا۟ ۩","tafsir":"لاهون وهذه الاستفهامات استنكارية."}]},"54":{"name":"القمر","verses":[{"text":"ٱقْتَرَبَتِ ٱلسَّاعَةُ وَٱنشَقَّ ٱلْقَمَرُ","tafsir":""},{"text":"وَإِن يَرَوْا۟ ءَايَةً يُعْرِضُوا۟ وَيَقُولُوا۟ سِحْرٌ مُّسْتَمِرٌّ","tafsir":"القيامة ، وفيها احتمالان كما تقدم في آخر السورة السابقة في « أزفت الآزفة » أو المراد أنه ليس بعد رسول الله صلى‌الله‌عليه‌وآله‌وسلم إلا الساعة ، فقد انتهت نبوات السماء به صلى‌الله‌عليه‌وآله‌وسلم ( وَانْشَقَّ الْقَمَرُ ) الذي هو من علامات اقتراب الساعة ، وقد كان ذلك معجزة لرسول الله صلى‌الله‌عليه‌وآله‌وسلم في قصة طويلة ، وقد نقل كتاب « الإسلام يتحدى » ذكر بعض التواريخ الغابرة رؤية الناس لهذا الانشقاق ، كما ذكرت بعض الجرائد الكويتية ـ بعد نزول الغربيين على القمر ـ رؤيتهم مكان الانشقاق كأنه صار نصفين ثم التحم ـ مع أنهم مسيحيون لا يؤمنون بنبوة محمد صلى‌الله‌عليه‌وآله‌وسلم ـ ."},{"text":"وَكَذَّبُوا۟ وَٱتَّبَعُوٓا۟ أَهْوَآءَهُمْ ۚ وَكُلُّ أَمْرٍ مُّسْتَقِرٌّ","tafsir":"هؤلاء الكفار المعاندون ( آيَةً ) معجزة تدل على صدق الرسول صلى‌الله‌عليه‌وآله‌وسلم ( يُعْرِضُوا ) عنها ولا يقبلونها ( وَيَقُولُوا ) إن ما يأتي به محمد صلى‌الله‌عليه‌وآله‌وسلم من الآيات ( سِحْرٌ مُسْتَمِرٌّ ) فهو يأتي بالسحر على سبيل الاستمرار."},{"text":"وَلَقَدْ جَآءَهُم مِّنَ ٱلْأَنۢبَآءِ مَا فِيهِ مُزْدَجَرٌ","tafsir":"بالحق لما جاءهم ( وَاتَّبَعُوا أَهْواءَهُمْ ) ما قرر عليهم الهوى والميل النفساني ، لا ما قرره عليهم عقلهم ( وَكُلُّ أَمْرٍ مُسْتَقِرٌّ ) وكل أمر لا بد وأن ينتهي إلى محل استقراره ، وهذا تهديد لهم ، أي أن تكذيبهم لا بد وأن ينتهي إلى عاقبة سيئة لهم."},{"text":"حِكْمَةٌۢ بَـٰلِغَةٌ ۖ فَمَا تُغْنِ ٱلنُّذُرُ","tafsir":"أي الأخبار بالله وبالآخرة ، وبجزاء المحسن ما فِيهِ مُزْدَجَرٌ (4) حِكْمَةٌ بالِغَةٌ فَما تُغْنِ النُّذُرُ (5) فَتَوَلَّ عَنْهُمْ يَوْمَ يَدْعُ الدَّاعِ إِلى شَيْءٍ نُكُرٍ (6) خُشَّعاً أَبْصارُهُمْ يَخْرُجُونَ مِنَ الْأَجْداثِ كَأَنَّهُمْ جَرادٌ مُنْتَشِرٌ (7) مُهْطِعِينَ إِلَى الدَّاعِ حسنا والمسيء سيئا ( ما فِيهِ ) كفاية و ( مُزْدَجَرٌ ) ازدجار ، مصدر ميمي ، فلو أنهم كانوا من أهل العقل والحكمة لكفاهم ما ذكرنا لهم من الوعيد ازدجارا. [6] ذلك الذي قلناه لهم من الأنباء ( حِكْمَةٌ بالِغَةٌ ) بلغتهم ، وقد كانت حكمة بوضع الشيء في موضعه ولكن ( فَما تُغْنِ ) ما تفيد ( النُّذُرُ ) الإنذارات ، بالنسبة إلى من يتعامى عنها."},{"text":"فَتَوَلَّ عَنْهُمْ ۘ يَوْمَ يَدْعُ ٱلدَّاعِ إِلَىٰ شَىْءٍ نُّكُرٍ","tafsir":""},{"text":"خُشَّعًا أَبْصَـٰرُهُمْ يَخْرُجُونَ مِنَ ٱلْأَجْدَاثِ كَأَنَّهُمْ جَرَادٌ مُّنتَشِرٌ","tafsir":"أعرض يا رسول الله ( عَنْهُمْ ) من بعد أن أبلغت وأنذرت ، ولم يقبلوا ، لأن الإنذار لا ينفع فيهم فما أهول ما ينتظرهم من العذاب في ( يَوْمَ يَدْعُ الدَّاعِ ) الداعي الذي يدعوهم عند البعث ، ليقوموا للحساب ( إِلى شَيْءٍ نُكُرٍ ) منكر فظيع ، وإنما كان منكرا ، لأن الإنسان لم يألفه ولم يشاهده."},{"text":"مُّهْطِعِينَ إِلَى ٱلدَّاعِ ۖ يَقُولُ ٱلْكَـٰفِرُونَ هَـٰذَا يَوْمٌ عَسِرٌ","tafsir":"جمع خاشع بمعنى الذليل ( أَبْصارُهُمْ ) فإن خشوع النفس يظهر من خشوع العين ( يَخْرُجُونَ ) في أثر النداء ( مِنَ الْأَجْداثِ ) جمع جدث ، بمعنى القبور ( كَأَنَّهُمْ جَرادٌ مُنْتَشِرٌ ) في الكثرة والتموّج وعدم النظام وانتشارهم في كل مكان."},{"text":"۞ كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ فَكَذَّبُوا۟ عَبْدَنَا وَقَالُوا۟ مَجْنُونٌ وَٱزْدُجِرَ","tafsir":"مسرعين ( إِلَى الدَّاعِ ) إلى الذي يدعوهم إلى الحساب ـ يَقُولُ الْكافِرُونَ هذا يَوْمٌ عَسِرٌ (8) كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ فَكَذَّبُوا عَبْدَنا وَقالُوا مَجْنُونٌ وَازْدُجِرَ (9) فَدَعا رَبَّهُ أَنِّي مَغْلُوبٌ فَانْتَصِرْ (10) فَفَتَحْنا أَبْوابَ السَّماءِ بِماءٍ مُنْهَمِرٍ (11) وَفَجَّرْنَا الْأَرْضَ عُيُوناً فَالْتَقَى الْماءُ عَلى أَمْرٍ قَدْ قُدِرَ (12) وَحَمَلْناهُ عَلى ويوم ذلك كلهم مطيعون ـ ( يَقُولُ الْكافِرُونَ هذا يَوْمٌ عَسِرٌ ) أي عسير صعب. [10] وهؤلاء الكفار بالإضافة إلى أنه ينتظرهم عذاب الآخرة ، كذلك مثلهم مثل الأقوام السابقة الذين كفروا بالأنبياء وبما جاءوا به فأخذهم عذاب الدنيا فقد ( كَذَّبَتْ قَبْلَهُمْ ) قبل قومك يا رسول الله ( قَوْمُ نُوحٍ ) فقد بغوا وطغوا وكذبوا ( عَبْدَنا ) نوحا عليه‌السلام ( وَقالُوا ) إنه ( مَجْنُونٌ ) كما يقول الكفار بالنسبة لك يا رسول الله ( وَازْدُجِرَ ) زجر نوح عليه‌السلام عن التبليغ بأنواع الأذية ، لكن نوحا عليه‌السلام استقام ولم ينصرف عن تبليغ الرسالة."},{"text":"فَدَعَا رَبَّهُۥٓ أَنِّى مَغْلُوبٌ فَٱنتَصِرْ","tafsir":""},{"text":"فَفَتَحْنَآ أَبْوَٰبَ ٱلسَّمَآءِ بِمَآءٍ مُّنْهَمِرٍ","tafsir":"نوح عليه‌السلام ( رَبَّهُ أَنِّي مَغْلُوبٌ ) قد غلب علي الكفار بقوتهم المادية ( فَانْتَصِرْ ) فانصرني يا رب عليهم. [12] وقد استجبنا دعاءه ( فَفَتَحْنا أَبْوابَ السَّماءِ ) مواضع نزول المطر ( بِماءٍ مُنْهَمِرٍ ) انهمر وتساقط بكثرة ، كأنه أفواه القرب."},{"text":"وَفَجَّرْنَا ٱلْأَرْضَ عُيُونًا فَٱلْتَقَى ٱلْمَآءُ عَلَىٰٓ أَمْرٍ قَدْ قُدِرَ","tafsir":""},{"text":"وَحَمَلْنَـٰهُ عَلَىٰ ذَاتِ أَلْوَٰحٍ وَدُسُرٍ","tafsir":"حتى كأنها لها عيون ( فَالْتَقَى الْماءُ ) ماء السماء وماء الأرض ( عَلى أَمْرٍ ) هو إغراق قوم نوح عليه‌السلام ( قَدْ قُدِرَ ) قدّره الله سبحانه وحكم به."},{"text":"تَجْرِى بِأَعْيُنِنَا جَزَآءً لِّمَن كَانَ كُفِرَ","tafsir":"أركبنا نوحا عليه‌السلام ومن معه من المؤمنين ( عَلى ) سفينة ذاتِ أَلْواحٍ وَدُسُرٍ (13) تَجْرِي بِأَعْيُنِنا جَزاءً لِمَنْ كانَ كُفِرَ (14) وَلَقَدْ تَرَكْناها آيَةً فَهَلْ مِنْ مُدَّكِرٍ (15) فَكَيْفَ كانَ عَذابِي وَنُذُرِ (16) وَلَقَدْ يَسَّرْنَا الْقُرْآنَ لِلذِّكْرِ فَهَلْ مِنْ مُدَّكِرٍ (17) كَذَّبَتْ عادٌ فَكَيْفَ كانَ عَذابِي وَنُذُرِ (18) ( ذاتِ أَلْواحٍ ) أخشاب عريضة ، جمع « لوح » ( وَدُسُرٍ ) المسامير ، فإنه جمع « دسار » بمعنى المسمار."},{"text":"وَلَقَد تَّرَكْنَـٰهَآ ءَايَةً فَهَلْ مِن مُّدَّكِرٍ","tafsir":"السفينة بالمياه المحيطة بالأرض ( بِأَعْيُنِنا ) تحت نظرنا ورعايتنا ، والجمع باعتبار أن كل حركة تحتاج إلى عين ترعاها من الغرق والهلاك ، وقد فعلنا ذلك بنوح عليه‌السلام ( جَزاءً ) حسنا منا ( لِمَنْ كانَ كُفِرَ ) لنوح الذي كفر به قومه."},{"text":"فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ","tafsir":"أبقينا خبر نوح وقومه ( آيَةً ) علامة يعتبر بها العقلاء ( فَهَلْ مِنْ مُدَّكِرٍ ) هل هناك من يعتبر بالقصة ؟ المبلغ يعتبر به فلا يهمه تكذيب الناس ، والناس يعتبرون فلا يكذبون المبلغين لأن عاقبتهم تكون سيئة."},{"text":"وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ","tafsir":"للمكذبين ( وَنُذُرِ ) إنذاراتي لهم ، ألم تكن عاقبة المكذبين العذاب كما وعدتهم ؟ [18] وهل يريدون أوضح بيانا من هذا الذي ذكرناه وخوفناهم به ؟ ( وَلَقَدْ يَسَّرْنَا ) سهّلنا ( الْقُرْآنَ لِلذِّكْرِ ) ليتذكر به الناس ( فَهَلْ مِنْ مُدَّكِرٍ ) من يتذكر ويتعظ ؟ استفهام تحريضي ، و « مدّكر » من « ادّكر » أصله « تذكّر » . [19] وبعد قوم نوح عليه‌السلام ( كَذَّبَتْ عادٌ ) قبيلة عاد وهم قوم هود عليه‌السلام ، فعذبناهم بتكذيبهم ( فَكَيْفَ كانَ عَذابِي وَنُذُرِ ) ؟ أليس في تكرار إِنَّا أَرْسَلْنا عَلَيْهِمْ رِيحاً صَرْصَراً فِي يَوْمِ نَحْسٍ مُسْتَمِرٍّ (19) تَنْزِعُ النَّاسَ كَأَنَّهُمْ أَعْجازُ نَخْلٍ مُنْقَعِرٍ (20) فَكَيْفَ كانَ عَذابِي وَنُذُرِ (21) وَلَقَدْ يَسَّرْنَا الْقُرْآنَ لِلذِّكْرِ فَهَلْ مِنْ مُدَّكِرٍ (22) العذاب لكل قوم كذبوا ، وعظا لكفار قريش ؟ فليس لهم أن يقولوا أن عذاب قوم نوح كان من القضايا الاتفاقية."},{"text":"كَذَّبَتْ عَادٌ فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ","tafsir":""},{"text":"إِنَّآ أَرْسَلْنَا عَلَيْهِمْ رِيحًا صَرْصَرًا فِى يَوْمِ نَحْسٍ مُّسْتَمِرٍّ","tafsir":""},{"text":"تَنزِعُ ٱلنَّاسَ كَأَنَّهُمْ أَعْجَازُ نَخْلٍ مُّنقَعِرٍ","tafsir":"على عاد ( رِيحاً صَرْصَراً ) باردة شديدة البرد ( فِي يَوْمِ نَحْسٍ ) شؤم عليهم ( مُسْتَمِرٍّ ) استمر العذاب عليهم في ذلك اليوم حتى أهلكهم."},{"text":"فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ","tafsir":"تقلع تلك الريح ( النَّاسَ ) قوم عاد ، من أماكنهم في الغرف وغيرها وكانت تفتح الأبواب وتخرج الناس إلى الساحات وترفعهم عن الأرض ثم تضربهم بها ، وكانت تقلع رؤوسهم عن أجسادهم فبقيت أجسادهم ( كَأَنَّهُمْ أَعْجازُ ) أصول ( نَخْلٍ مُنْقَعِرٍ ) منقلع عن مغارسه ، ولعلهم كانوا يلوون على أنفسهم من شدة الألم ولأن يجمعوا أنفسهم في قبال الريح ، ولذا شبهوا بأعجاز النخل."},{"text":"وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ","tafsir":"؟ لعل وجه التكرار لأجل أن مثل هذا العذاب لا يمكن أن يحمل على أنه طبيعي ، وإن أمكن ذلك في الغرق."},{"text":"كَذَّبَتْ ثَمُودُ بِٱلنُّذُرِ","tafsir":"فلم نجعله كالكتب الفلسفية التي لا يفهمها الإنسان إلا بصعوبة بالغة ( فَهَلْ مِنْ مُدَّكِرٍ ) ؟ من يتذكر فلا يعصي حتى لا يعذب كما عذب الأمم السابقة. كَذَّبَتْ ثَمُودُ بِالنُّذُرِ (23) فَقالُوا أَ بَشَراً مِنَّا واحِداً نَتَّبِعُهُ إِنَّا إِذاً لَفِي ضَلالٍ وَسُعُرٍ (24) أَأُلْقِيَ الذِّكْرُ عَلَيْهِ مِنْ بَيْنِنا بَلْ هُوَ كَذَّابٌ أَشِرٌ (25) سَيَعْلَمُونَ غَداً مَنِ الْكَذَّابُ الْأَشِرُ (26) إِنَّا مُرْسِلُوا النَّاقَةِ"},{"text":"فَقَالُوٓا۟ أَبَشَرًا مِّنَّا وَٰحِدًا نَّتَّبِعُهُۥٓ إِنَّآ إِذًا لَّفِى ضَلَـٰلٍ وَسُعُرٍ","tafsir":"قبيلة ( ثَمُودُ ) قوم صالح عليه‌السلام ( بِالنُّذُرِ ) جمع نذير أي الأنبياء إذ تكذيب نبي واحد هو تكذيب لكل الأنبياء."},{"text":"أَءُلْقِىَ ٱلذِّكْرُ عَلَيْهِ مِنۢ بَيْنِنَا بَلْ هُوَ كَذَّابٌ أَشِرٌ","tafsir":"من جنسنا أو من قبيلتنا ، لأن صالح كان من قبيلتهم ( واحِداً ) لا تبع له ( نَتَّبِعُهُ ) ونقبل كلامه ؟ هذا لا يكون ( إِنَّا إِذاً ) إذا اتبعنا بشرا واحدا ( لَفِي ضَلالٍ ) عن طريقة آبائنا ( وَسُعُرٍ ) جمع سعير ، أي نحرق بناره ، كما يقال فلان أحرق نفسه أي سبّب ضياع نفسه وماله ومستقبله ، إنهم ما كانوا يقتنعون بالبرهان ، بل كانوا يريدون أن يكون الهادي لهم من جنس أعلى كالملائكة لا « منا » أو لهم جماعة وسطوة وشوكة مثل أن يكون ملكا أو رئيس عشيرة."},{"text":"سَيَعْلَمُونَ غَدًا مَّنِ ٱلْكَذَّابُ ٱلْأَشِرُ","tafsir":"الكتاب والوحي ( عَلَيْهِ مِنْ بَيْنِنا ) ؟ فلما ذا لم يلق الوحي إلي من هو أكثر منه مالا أو شخصية ؟ ( بَلْ هُوَ ) صالح عليه‌السلام ( كَذَّابٌ ) كثير الكذب في نسبة الوحي إلى نفسه ( أَشِرٌ ) حمله بطره على الترفع علينا بادعائه النبوة ، فإن المترفعين لما يعتادون الإشارة إلى الناس بالاستهزاء والسوء ، اشتق من مادة الإشارة ، الأشر بهذا المعنى."},{"text":"إِنَّا مُرْسِلُوا۟ ٱلنَّاقَةِ فِتْنَةً لَّهُمْ فَٱرْتَقِبْهُمْ وَٱصْطَبِرْ","tafsir":"حين ينزل عليهم العذاب ( مَنِ ) هو ( الْكَذَّابُ الْأَشِرُ ) هل هم الذين أكثروا من الكذب أم صالح النبي عليه‌السلام ؟."},{"text":"وَنَبِّئْهُمْ أَنَّ ٱلْمَآءَ قِسْمَةٌۢ بَيْنَهُمْ ۖ كُلُّ شِرْبٍ مُّحْتَضَرٌ","tafsir":"أي الله سبحانه ( مُرْسِلُوا النَّاقَةِ ) مخرجوها من الجبل وباعثوها فِتْنَةً لَهُمْ فَارْتَقِبْهُمْ وَاصْطَبِرْ (27) وَنَبِّئْهُمْ أَنَّ الْماءَ قِسْمَةٌ بَيْنَهُمْ كُلُّ شِرْبٍ مُحْتَضَرٌ (28) فَنادَوْا صاحِبَهُمْ فَتَعاطى فَعَقَرَ (29) فَكَيْفَ كانَ عَذابِي وَنُذُرِ (30) إِنَّا أَرْسَلْنا عَلَيْهِمْ صَيْحَةً واحِدَةً فَكانُوا كَهَشِيمِ الْمُحْتَظِرِ (31) إليهم معجزة لصالح عليه‌السلام ( فِتْنَةً ) اختبارا وامتحانا ( لَهُمْ ) هل يؤمنون بالإعجاز أم لا ؟ ( فَارْتَقِبْهُمْ ) أي انتظرهم وراقبهم هل يؤمنون أم لا ؟ ( وَاصْطَبِرْ ) عليهم بالاستمرار في التبليغ وعدم الدعاء عليهم مع إيذائهم لك."},{"text":"فَنَادَوْا۟ صَاحِبَهُمْ فَتَعَاطَىٰ فَعَقَرَ","tafsir":"أخبرهم ( أَنَّ الْماءَ ) الذي كان يجري نهرا عندهم ( قِسْمَةٌ بَيْنَهُمْ ) مقسوم للناقة يوم ولهم يوم ، فإذا شربت الناقة في يومها كل ماء النهر أعطتهم عوضه حليبا ( كُلُّ شِرْبٍ ) شرب الحصة من الماء ( مُحْتَضَرٌ ) يحضره صاحبه ولا حق لأحدهما في الماء في يوم الآخر."},{"text":"فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ","tafsir":"ثمود ( صاحِبَهُمْ ) وهو قدار الذي كان من شرارهم ( فَتَعاطى ) أخذ الناقة ، ولعل باب التفاعل من جهة أن قدار وجماعة منهم أخذوا زمام الناقة حتى ألجؤوها إلى مكان يمكن عقرها ( فَعَقَرَ ) قدار الناقة أي جرحها وقتلها."},{"text":"إِنَّآ أَرْسَلْنَا عَلَيْهِمْ صَيْحَةً وَٰحِدَةً فَكَانُوا۟ كَهَشِيمِ ٱلْمُحْتَظِرِ","tafsir":"؟ هل تركت عذابهم لما خالفوا وكذبوا أم أخذتهم بالعذاب ؟."},{"text":"وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ","tafsir":"صاح بهم جبرائيل عليه‌السلام فانخلعت بذلك قلوبهم ( فَكانُوا كَهَشِيمِ الْمُحْتَظِرِ ) كالحشيش اليابس الذي يجمعه صاحب الماشية في الشتاء في حظيرته ، ولعل وجه التشبيه ، أنه وَلَقَدْ يَسَّرْنَا الْقُرْآنَ لِلذِّكْرِ فَهَلْ مِنْ مُدَّكِرٍ (32) كَذَّبَتْ قَوْمُ لُوطٍ بِالنُّذُرِ (33) إِنَّا أَرْسَلْنا عَلَيْهِمْ حاصِباً إِلاَّ آلَ لُوطٍ نَجَّيْناهُمْ بِسَحَرٍ (34) نِعْمَةً مِنْ عِنْدِنا كَذلِكَ نَجْزِي مَنْ شَكَرَ (35) تقطعت أيديهم وأرجلهم وتكوّمت الأبدان والأيدي والأرجل في مكان ، كما يتكوّم الهشيم المتكسر المجتمع."},{"text":"كَذَّبَتْ قَوْمُ لُوطٍۭ بِٱلنُّذُرِ","tafsir":"لا يقال في القرآن متشابهات ، لأنه يقال عامة القرآن ميسرة وبعض الآيات المتشابهات لا يضر بالعموم من حيث العموم."},{"text":"إِنَّآ أَرْسَلْنَا عَلَيْهِمْ حَاصِبًا إِلَّآ ءَالَ لُوطٍ ۖ نَّجَّيْنَـٰهُم بِسَحَرٍ","tafsir":"فلم يقبلوا إنذار لوط عليه‌السلام وتكذيب لوط تكذيب لسائر الأنبياء."},{"text":"نِّعْمَةً مِّنْ عِندِنَا ۚ كَذَٰلِكَ نَجْزِى مَن شَكَرَ","tafsir":"جزاء لتكذيبهم ( أَرْسَلْنا عَلَيْهِمْ حاصِباً ) ريحا ترميهم بالحجارة يقال حصبه أي رماه بالحجارة ( إِلَّا آلَ لُوطٍ ) لوط وأهل بيته المؤمنين « باستثناء زوجته فإنها أصابها ما أصاب القوم لأنها كانت كافرة مثلهم » ( نَجَّيْناهُمْ بِسَحَرٍ ) في آخر الليل. [36] وإنما نجيناهم ( نِعْمَةً ) لهم ( مِنْ عِنْدِنا ) إذ كان من الممكن إماتتهم في ذلك الحال ، بدون عذاب ، كما يموت كل خير في زمان ما ( كَذلِكَ ) هكذا ، كما جزينا آل لوط عليه‌السلام ( نَجْزِي مَنْ شَكَرَ ) نعمتنا عليه ، بالإيمان والطاعة ، والمراد الشكر القلبي والشكر العملي. [37] وقد قدم سبحانه عذابهم على ذكر بلاغ لوط لهم ، لبيان أن العذاب وَلَقَدْ أَنْذَرَهُمْ بَطْشَتَنا فَتَمارَوْا بِالنُّذُرِ (36) وَلَقَدْ راوَدُوهُ عَنْ ضَيْفِهِ فَطَمَسْنا أَعْيُنَهُمْ فَذُوقُوا عَذابِي وَنُذُرِ (37) وَلَقَدْ صَبَّحَهُمْ بُكْرَةً عَذابٌ مُسْتَقِرٌّ (38) فَذُوقُوا عَذابِي وَنُذُرِ (39) يأخذ المعتدين بسرعة حتى كأن بقاءهم في الحياة لمحة عين ( وَلَقَدْ أَنْذَرَهُمْ ) لوط عليه‌السلام ( بَطْشَتَنا ) أخذنا الشديد بالعذاب لمن خالف أوامرنا ( فَتَمارَوْا ) فتشككوا من المماراة أي المجادلة ( بِالنُّذُرِ ) وأخذوا يجادلون بالباطل حول صدق لوط."},{"text":"وَلَقَدْ أَنذَرَهُم بَطْشَتَنَا فَتَمَارَوْا۟ بِٱلنُّذُرِ","tafsir":""},{"text":"وَلَقَدْ رَٰوَدُوهُ عَن ضَيْفِهِۦ فَطَمَسْنَآ أَعْيُنَهُمْ فَذُوقُوا۟ عَذَابِى وَنُذُرِ","tafsir":""},{"text":"وَلَقَدْ صَبَّحَهُم بُكْرَةً عَذَابٌ مُّسْتَقِرٌّ","tafsir":"لم يقتنعوا بتكذيبه والاستمرار في فحشائهم ، بل أضافوا على ذلك أنهم ( لَقَدْ راوَدُوهُ عَنْ ضَيْفِهِ ) المراودة ، الرواح والمجيء ، فقد جاء آل لوط ضيوف ، فأراد قومه أن يلوطوا بهم ، وكان أولئك الضيوف هم الملائكة ( فَطَمَسْنا أَعْيُنَهُمْ ) فمسحناها وسويناها بسائر الوجه حتى عميت عيونهم وشوهت خلقتهم فقلنا لهم ( فَذُوقُوا عَذابِي وَنُذُرِ ) أي ذوقوا عاقبة إنذاري لكم ، أو المراد كأن لسان الحال يقول لهم « ذوقوا .. . » ."},{"text":"فَذُوقُوا۟ عَذَابِى وَنُذُرِ","tafsir":"دخل العذاب عليهم في الصباح الباكر ، والبكرة أول الصبح ، ودخول العذاب في ذلك الوقت أنكر ، لأنهم يرجون خير النهار فإذا بهم يجدون انهدام الآمال بالعذاب ( مُسْتَقِرٌّ ) فلم يكن عذابا عابرا ، بل عذاب استقر بهم حتى أهلكهم."},{"text":"وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ","tafsir":"وفائدة التكرار تكرار التذكير ومن الواضح أنه قد يؤثر التكرار ما لا يؤثر غيره ، وذلك لاستيعاب الذهن له ، ولذا إذا أراد الإنسان أن يحفظ شيئا كرره مرات. وَلَقَدْ يَسَّرْنَا الْقُرْآنَ لِلذِّكْرِ فَهَلْ مِنْ مُدَّكِرٍ (40) وَلَقَدْ جاءَ آلَ فِرْعَوْنَ النُّذُرُ (41) كَذَّبُوا بِآياتِنا كُلِّها فَأَخَذْناهُمْ أَخْذَ عَزِيزٍ مُقْتَدِرٍ (42) أَ كُفَّارُكُمْ خَيْرٌ مِنْ أُولئِكُمْ أَمْ لَكُمْ بَراءَةٌ فِي الزُّبُرِ (43)"},{"text":"وَلَقَدْ جَآءَ ءَالَ فِرْعَوْنَ ٱلنُّذُرُ","tafsir":"لا يقال غير العرب لا يستفيدون من القرآن ، لأنه يقال ، قصد الإسلام توحيد لغة الناس ، لأجل تفاهم عام ولأجل إرساء دعائم حكومة واحدة ـ بما فيها من الفوائد الجمة ـ ومثل ذلك يوجب يسر القرآن للكل."},{"text":"كَذَّبُوا۟ بِـَٔايَـٰتِنَا كُلِّهَا فَأَخَذْنَـٰهُمْ أَخْذَ عَزِيزٍ مُّقْتَدِرٍ","tafsir":"آل فلان يستعمل له ولآله ، أي فرعون وآله ( النُّذُرُ ) المنذرون مثل موسى وهارون ومؤمن آل فرعون ، ولعل أنبياء آخرين أيضا كانوا ، لما ورد في الأحاديث أن موسى عليه‌السلام حج مع سبعين نبيا."},{"text":"أَكُفَّارُكُمْ خَيْرٌ مِّنْ أُو۟لَـٰٓئِكُمْ أَمْ لَكُم بَرَآءَةٌ فِى ٱلزُّبُرِ","tafsir":"الكثيرة ( كُلِّها ) كاليد والعصا والقمل والضفادع والدم وغيرها ، ولعل المجيء بدون « الواو » لإفادة فورية التكذيب بلا تروّ ( فَأَخَذْناهُمْ ) بالغرق ( أَخْذَ عَزِيزٍ ) له العزة والغلبة ( مُقْتَدِرٍ ) له القدرة ، لأن القدرة قد تكون مع الذلة عند الناس ، وقد تكون مع العزة."},{"text":"أَمْ يَقُولُونَ نَحْنُ جَمِيعٌ مُّنتَصِرٌ","tafsir":"يا معشر قريش ( خَيْرٌ مِنْ أُولئِكُمْ ) من أولئك الكفار للأمم السابقة حتى نترككم مع تكذيبكم ، وقد سمعتم كيف أخذنا أولئك الكفار ؟ ( أَمْ لَكُمْ بَراءَةٌ فِي الزُّبُرِ ) في الكتب ، بأن كنا أعطيناكم عهدا في كتب الأنبياء أن لا نهلككم ؟ وإذ لا ذاك ، ولا هذا ، فاللازم أن أَمْ يَقُولُونَ نَحْنُ جَمِيعٌ مُنْتَصِرٌ (44) سَيُهْزَمُ الْجَمْعُ وَيُوَلُّونَ الدُّبُرَ (45) بَلِ السَّاعَةُ مَوْعِدُهُمْ وَالسَّاعَةُ أَدْهى وَأَمَرُّ (46) إِنَّ الْمُجْرِمِينَ فِي ضَلالٍ وَسُعُرٍ (47) يَوْمَ تخافوا من بطشنا وأن نفعل بكم ما فعلنا بتلك الأمم الكافرة."},{"text":"سَيُهْزَمُ ٱلْجَمْعُ وَيُوَلُّونَ ٱلدُّبُرَ","tafsir":"هؤلاء الكفار ( نَحْنُ جَمِيعٌ ) مجتمع ( مُنْتَصِرٌ ) ننتصر ونتغلب على من أراد بنا هلاكا ؟ وهل يمكن التغلب على إرادة الله ؟."},{"text":"بَلِ ٱلسَّاعَةُ مَوْعِدُهُمْ وَٱلسَّاعَةُ أَدْهَىٰ وَأَمَرُّ","tafsir":"سيهزمون إذا جاءهم عذاب الله ولا يفيدهم جمعهم ( وَيُوَلُّونَ الدُّبُرَ ) فلا يقفون وجها لوجه أمام العذاب ، بل يعطون العذاب قفاهم ويفرون ، فلا يفيدهم جمعهم. [47] هذا إذا أرسلنا عليهم العذاب في الدنيا ( بَلِ السَّاعَةُ ) القيامة ( مَوْعِدُهُمْ ) موعد عقوبتهم الحقيقية وعذابهم الأصلي ( وَالسَّاعَةُ أَدْهى ) أشد عذابا لهم من عذاب الدنيا ( وَأَمَرُّ ) أكثر مرارة في مذاقهم ، والداهية الأمر المنكر الذي لا يهتدي الإنسان لدوائه."},{"text":"إِنَّ ٱلْمُجْرِمِينَ فِى ضَلَـٰلٍ وَسُعُرٍ","tafsir":""},{"text":"يَوْمَ يُسْحَبُونَ فِى ٱلنَّارِ عَلَىٰ وُجُوهِهِمْ ذُوقُوا۟ مَسَّ سَقَرَ","tafsir":"بالإضافة إلى عذابهم في الدنيا والآخرة ، هم ( فِي ضَلالٍ ) عن الحق ، وهذا ما يولد لهم نوعا من المشاكل المادية ، لأن غير طريق الحق فيه مشاكل وأتعاب ( وَسُعُرٍ ) جمع سعير ، لأنهم يستعرون نفسيا بما يرتطمون فيه من المشاكل فهم في قلق نفسي واضطراب وعدم سكينة ، فإن الاطمئنان النفسي للمؤمنين فقط ، أو المراد ضلال الدنيا وسعير الآخرة."},{"text":"إِنَّا كُلَّ شَىْءٍ خَلَقْنَـٰهُ بِقَدَرٍ","tafsir":"بيان لموعدهم في الساعة ، أو ما بينه بقوله « سعر » يُسْحَبُونَ فِي النَّارِ عَلى وُجُوهِهِمْ ذُوقُوا مَسَّ سَقَرَ (48) إِنَّا كُلَّ شَيْءٍ خَلَقْناهُ بِقَدَرٍ (49) وَما أَمْرُنا إِلاَّ واحِدَةٌ كَلَمْحٍ بِالْبَصَرِ (50) و َلَقَدْ أَهْلَكْنا أَشْياعَكُمْ ( يُسْحَبُونَ ) يجرون ( فِي النَّارِ عَلى وُجُوهِهِمْ ) فإنهم لما لم تخضع وجوههم للحق ، جوزوا بإذلال وجوههم في النار ، ويقال لهم زيادة في إهانتهم من جهة الشماتة ( ذُوقُوا مَسَّ سَقَرَ ) مسّه ، أي أصابه ، وسقر علم على جهنم. [50] وحيث إن الكفار كانوا يقولون : ائتنا بعذاب الله إن كنت صادقا ، أجابهم القرآن ( إِنَّا كُلَّ شَيْءٍ خَلَقْناهُ ) أي جعلناه ( بِقَدَرٍ ) بتقدير خاص ، فيوم القيامة ، وعذاب هؤلاء ، يأتي في الوقت المقدر لهما ، ولا نقدم العذاب حسب طلبهم فكما أن كل بذرة تعطي ثمرا ، فللثمرة بين زرعها وبين إثمارها زمان مقدر ، كذلك كل عمل إلى أن يعطي ثمره وجزاءه له وقت مقدر خاص. [51] لكن إذا حان الوقت المقدر ، فلا تراجع فيه ولا بطء فيه ( وَما أَمْرُنا ) بعذابهم أو بغير ذلك ( إِلَّا واحِدَةٌ ) فلا حاجة للتكرار في الأمر ، كما لا تراجع منه إذا أمرنا وهو ( كَلَمْحٍ بِالْبَصَرِ ) حركة البصر ، في السرعة فلا يحتاج إلى مقدمات فيجب أن يعرف هؤلاء الكفار أنه إذا حان عذابهم لا تراجع فيه ، كما أنه لا يأخذهم تدريجيا ليفكروا في الخلاص بل يأخذهم بغتة."},{"text":"وَمَآ أَمْرُنَآ إِلَّا وَٰحِدَةٌ كَلَمْحٍۭ بِٱلْبَصَرِ","tafsir":""},{"text":"وَلَقَدْ أَهْلَكْنَآ أَشْيَاعَكُمْ فَهَلْ مِن مُّدَّكِرٍ","tafsir":""},{"text":"وَكُلُّ شَىْءٍ فَعَلُوهُ فِى ٱلزُّبُرِ","tafsir":"أشباهكم من الأمم ، وقد عرفتم كيف لم نتراجع حين أردنا عذابهم وكيف لم نتدرج في عذابهم بل أخذناهم فَهَلْ مِنْ مُدَّكِرٍ (51) وَكُلُّ شَيْءٍ فَعَلُوهُ فِي الزُّبُرِ (52) وَكُلُّ صَغِيرٍ وَكَبِيرٍ مُسْتَطَرٌ (53) إِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ وَنَهَرٍ (54) فِي مَقْعَدِ صِدْقٍ عِنْدَ مَلِيكٍ مُقْتَدِرٍ (55) دفعة واحدة ( فَهَلْ مِنْ مُدَّكِرٍ ) مدّكر يتذكر ، حتى يرجع عن غيه ؟. [53] ولم ننس حتى أصغر شيء فعلوه فعاقبناهم بكل ما ارتكبوا من جرائم ( وَكُلُّ شَيْءٍ فَعَلُوهُ ) مكتوب ( فِي الزُّبُرِ ) كتبه الحفظة."},{"text":"وَكُلُّ صَغِيرٍ وَكَبِيرٍ مُّسْتَطَرٌ","tafsir":""},{"text":"إِنَّ ٱلْمُتَّقِينَ فِى جَنَّـٰتٍ وَنَهَرٍ","tafsir":"من أعمالهم ، كما هو كذلك في كل أعمال البشر ( مُسْتَطَرٌ ) مسطور مكتوب."},{"text":"فِى مَقْعَدِ صِدْقٍ عِندَ مَلِيكٍ مُّقْتَدِرٍۭ","tafsir":"جمع نهر بسكون الهاء ، ولعل المراد انهم يسبحون في أنهار الجنة ، والظرف مجاز."}]}});
